:root {
  --ink: #0d0918;
  --ink-2: #17102a;
  --panel: rgba(20, 14, 38, 0.72);
  --panel-solid: #1b1330;
  --line: rgba(255, 255, 255, 0.14);
  --line-hot: rgba(255, 225, 74, 0.72);
  --yellow: #ffe14a;
  --yellow-hot: #fff59a;
  --purple: #9d63ff;
  --purple-deep: #5b2fc7;
  --cyan: #58eeff;
  --coral: #ff6d72;
  --green: #6df08a;
  --text: #f7f3ff;
  --muted: #a79bc4;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  --display: "Arial Black", "Arial Bold", "DejaVu Sans", Impact, sans-serif;
  --ui: "Trebuchet MS", "Segoe UI", "DejaVu Sans", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a0714;
  color: var(--text);
  font-family: var(--ui);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

button { font: inherit; color: inherit; }
#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.hidden { display: none !important; }

/* ---------- HUD shell ---------- */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  padding: max(18px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hud-grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.16;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
}

.panel {
  background:
    linear-gradient(145deg, rgba(255,255,255,0.075), rgba(255,255,255,0.012) 42%, rgba(0,0,0,0.1)),
    var(--panel);
  border: 1px solid var(--line);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,0.1);
  backdrop-filter: blur(14px) saturate(1.2);
  -webkit-backdrop-filter: blur(14px) saturate(1.2);
}

.eyebrow {
  font-family: var(--display);
  font-size: 10px;
  line-height: 1;
  letter-spacing: 1.7px;
  color: var(--muted);
  text-transform: uppercase;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  position: relative;
  z-index: 2;
}

.turn-card {
  width: 242px;
  border-radius: 18px;
  padding: 14px 16px 13px;
  position: relative;
  overflow: hidden;
}
.turn-card::after {
  content: "";
  position: absolute;
  left: 0; bottom: 0; height: 3px; width: 100%;
  background: linear-gradient(90deg, var(--yellow), transparent 70%);
  opacity: .8;
}
.turn-meta { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 7px; }
.phase-tag {
  font-family: var(--display);
  font-size: 9px;
  letter-spacing: 1.2px;
  color: var(--ink);
  background: var(--yellow);
  border-radius: 4px;
  padding: 3px 7px 2px;
}
.turn-label {
  font-family: var(--display);
  font-size: 27px;
  line-height: .98;
  letter-spacing: -0.6px;
  text-transform: uppercase;
  text-shadow: 0 3px 0 rgba(0,0,0,.35);
}
.turn-label.enemy { color: var(--coral); }
.turn-label.player { color: var(--yellow); }
.timer-line { display: flex; align-items: center; gap: 9px; margin-top: 9px; }
.timer-track { height: 6px; flex: 1; border-radius: 99px; background: rgba(0,0,0,.42); overflow: hidden; box-shadow: inset 0 1px 2px rgba(0,0,0,.5); }
.timer-track i { display: block; height: 100%; width: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--yellow), #ff9d3d); transition: width .18s linear, background .3s; }
.timer-track i.danger { background: linear-gradient(90deg, #ff4d56, #ff9f39); }
.timer-value { font-family: var(--display); font-size: 18px; width: 30px; text-align: right; font-variant-numeric: tabular-nums; }

.wind-card { width: 154px; border-radius: 18px; padding: 12px 14px; }
.wind-caption { display: flex; align-items: center; gap: 6px; font-family: var(--display); font-size: 9px; letter-spacing: 1.6px; color: var(--muted); }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 9px var(--cyan); animation: pulse 1.6s ease-in-out infinite; }
.wind-body { display: flex; align-items: baseline; gap: 5px; margin: 4px 0 2px; }
.wind-arrow { display: inline-block; font-size: 20px; color: var(--cyan); transform-origin: 50% 55%; transition: transform .6s cubic-bezier(.2,.9,.2,1); text-shadow: 0 0 13px rgba(88,238,255,.6); }
.wind-value { font-family: var(--display); font-size: 25px; line-height: 1; }
.wind-unit { font-size: 9px; letter-spacing: .8px; color: var(--muted); text-transform: uppercase; }
.wind-track { height: 3px; border-radius: 9px; background: rgba(255,255,255,.09); position: relative; overflow: hidden; }
.wind-track::after { content:""; position:absolute; left:50%; top:-2px; width:1px; height:7px; background:rgba(255,255,255,.35); }
.wind-track i { display: block; height: 100%; width: 50%; margin-left: 0; background: linear-gradient(90deg, transparent, var(--cyan)); border-radius: inherit; }

.scoreboard { margin-left: auto; border-radius: 18px; padding: 10px 14px; display: flex; align-items: center; gap: 14px; min-width: 382px; }
.team-panel { min-width: 148px; }
.team-heading { display: flex; align-items: center; gap: 6px; font-family: var(--display); font-size: 9px; letter-spacing: 1.2px; color: var(--muted); white-space: nowrap; }
.team-heading em { font-style: normal; margin-left: auto; color: rgba(255,255,255,.8); font-size: 8px; }
.team-swatch { width: 7px; height: 7px; border-radius: 2px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.team-enemy .team-swatch { background: var(--coral); box-shadow: 0 0 8px var(--coral); }
.team-enemy .team-heading { justify-content: flex-end; }
.members { display: flex; flex-direction: column; gap: 5px; margin-top: 7px; }
.team-enemy .members { align-items: flex-end; }
.member { display: flex; align-items: center; gap: 6px; width: 138px; opacity: .92; transition: opacity .25s, transform .25s; }
.team-enemy .member { flex-direction: row-reverse; }
.member.dead { opacity: .25; filter: grayscale(1); }
.member.active { opacity: 1; transform: translateX(2px); }
.team-enemy .member.active { transform: translateX(-2px); }
.member-name { font-family: var(--display); font-size: 8px; letter-spacing: .8px; color: var(--muted); width: 35px; }
.member.active .member-name { color: var(--text); }
.member-hp { flex: 1; height: 5px; background: rgba(0,0,0,.4); border-radius: 9px; overflow: hidden; }
.member-hp i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #2ed9c3, #7cf7c9); border-radius: inherit; transition: width .35s cubic-bezier(.2,.8,.2,1), background .3s; }
.team-enemy .member-hp i { background: linear-gradient(90deg, #ff8d5f, #ff5b74); }
.member.low .member-hp i { background: linear-gradient(90deg, #ff4c4c, #ffb347); }
.versus { font-family: var(--display); font-size: 10px; color: rgba(255,255,255,.28); letter-spacing: 1px; transform: rotate(-8deg); }

/* ---------- toast ---------- */
.toast {
  position: absolute;
  left: 50%; top: 132px;
  transform: translate(-50%, -14px) scale(.92);
  opacity: 0;
  pointer-events: none;
  background: var(--yellow);
  color: var(--ink);
  font-family: var(--display);
  font-size: 14px;
  letter-spacing: 1.5px;
  padding: 9px 17px 8px;
  border-radius: 8px;
  border: 2px solid #190f2f;
  box-shadow: 4px 5px 0 rgba(16,9,32,.75), 0 12px 30px rgba(0,0,0,.35);
  transition: opacity .22s, transform .28s cubic-bezier(.2,1.5,.3,1);
  z-index: 4;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.toast.bad { background: var(--coral); color: #25070e; }

/* ---------- bottom HUD ---------- */
.hud-bottom {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  position: relative;
  z-index: 3;
}

.operator-card {
  width: 288px;
  border-radius: 18px;
  padding: 13px 14px 12px;
  flex: none;
}
.operator-top { display: flex; gap: 11px; align-items: center; }
.avatar {
  width: 47px; height: 47px; border-radius: 13px;
  background: radial-gradient(circle at 35% 25%, #2a5b56, #112b31 70%);
  border: 1px solid rgba(88,238,255,.45);
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 0 18px rgba(88,238,255,.18);
  flex: none;
}
.avatar span {
  position: absolute; left: 8px; right: 8px; bottom: 7px; height: 18px;
  border-radius: 54% 46% 40% 40%;
  background: linear-gradient(180deg, #7ef4c2, #2bbf8a);
  box-shadow: 0 4px 0 rgba(0,0,0,.2);
}
.avatar i {
  position: absolute; left: 15px; top: 11px; width: 6px; height: 6px; border-radius: 50%;
  background: #10131c; box-shadow: 10px 1px 0 #10131c, 0 0 0 2px rgba(255,255,255,.16);
}
.operator-id { flex: 1; min-width: 0; }
.operator-name { font-family: var(--display); font-size: 22px; line-height: 1.02; letter-spacing: .3px; }
.hp-line { display: flex; align-items: center; gap: 7px; margin-top: 4px; }
.hp-track { height: 6px; flex: 1; border-radius: 9px; background: rgba(0,0,0,.42); overflow: hidden; }
.hp-track i { display: block; height: 100%; width: 100%; border-radius: inherit; background: linear-gradient(90deg, #2ddbbd, #97ffc6); transition: width .3s; }
.hp-line span { font-family: var(--display); font-size: 11px; width: 25px; text-align: right; color: var(--green); }

.materials { display: flex; gap: 6px; margin-top: 10px; }
.mat {
  flex: 1;
  display: flex; align-items: center; gap: 4px;
  background: rgba(0,0,0,.28);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 8px;
  padding: 5px 6px;
  color: var(--text);
  cursor: pointer;
  pointer-events: auto;
  transition: border-color .2s, background .2s, transform .15s;
  min-width: 0;
}
.mat:hover { background: rgba(255,255,255,.09); transform: translateY(-1px); }
.mat.active { border-color: var(--yellow); background: rgba(255,225,74,.13); box-shadow: inset 0 0 12px rgba(255,225,74,.08); }
.mat svg { width: 17px; height: 17px; flex: none; filter: drop-shadow(0 1px 1px rgba(0,0,0,.5)); }
.mat-count { font-family: var(--display); font-size: 12px; min-width: 22px; }
.mat b { margin-left: auto; font-family: var(--display); font-size: 7px; color: var(--muted); border: 1px solid rgba(255,255,255,.18); border-radius: 3px; padding: 2px 3px; }

.loadout {
  margin-left: auto;
  width: min(690px, 52vw);
  border-radius: 18px;
  padding: 10px 12px 11px;
}
.loadout-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; }
.pill { font-family: var(--display); font-size: 8px; letter-spacing: 1px; color: var(--ink); background: var(--yellow); border-radius: 4px; padding: 3px 6px; }
.pill.subtle { background: rgba(255,255,255,.12); color: var(--muted); }
.weapon-head { margin-top: 8px; }
.build-bar, .weapon-bar { display: flex; gap: 6px; }
.loadout-btn {
  position: relative;
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  text-align: left;
  background: rgba(9,6,18,.42);
  border: 1px solid rgba(255,255,255,.11);
  border-radius: 10px;
  padding: 7px 8px;
  cursor: pointer;
  pointer-events: auto;
  transition: border-color .18s, background .18s, transform .12s, box-shadow .18s;
  overflow: hidden;
}
.loadout-btn::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(115deg, transparent 35%, rgba(255,255,255,.12) 50%, transparent 65%);
  transform: translateX(-120%);
  transition: transform .5s;
}
.loadout-btn:hover { transform: translateY(-2px); border-color: rgba(255,255,255,.28); background: rgba(255,255,255,.075); }
.loadout-btn:hover::after { transform: translateX(120%); }
.loadout-btn.active {
  background: linear-gradient(145deg, var(--yellow-hot), var(--yellow) 58%, #ffc531);
  border-color: #fff6ad;
  color: var(--ink);
  box-shadow: 0 0 0 1px rgba(255,225,74,.3), 0 6px 20px rgba(255,213,48,.24), inset 0 1px 0 rgba(255,255,255,.8);
}
.loadout-btn.active .key { background: rgba(16,9,32,.85); color: var(--yellow); border-color: transparent; }
.loadout-btn.active .loadout-copy small { color: rgba(20,12,38,.66); }
.loadout-btn.active .icon i,
.loadout-btn.active .icon i::after { background: #1b1030; border-color: #1b1030; }
.loadout-btn.active .icon-ramp i { background: linear-gradient(135deg, #1b1030 49%, transparent 50%); }
.loadout-btn.active .icon-grenade i { border-color: #1b1030; background: #1b1030; }
.key {
  position: absolute; top: 4px; right: 5px;
  font-family: var(--display); font-size: 7px; line-height: 1;
  color: var(--muted);
  border: 1px solid rgba(255,255,255,.17);
  border-radius: 3px;
  padding: 2px 3px 1px;
}
.loadout-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.loadout-copy strong { font-family: var(--display); font-size: 10px; letter-spacing: .45px; }
.loadout-copy small { font-size: 9px; color: var(--muted); letter-spacing: .4px; }
.loadout-copy small.ammo { font-family: var(--display); }

.icon { position: relative; width: 25px; height: 25px; flex: none; }
.icon-wall i { position: absolute; bottom: 3px; width: 5px; height: 18px; background: #c69258; border-radius: 1px; }
.icon-wall i:nth-child(1) { left: 2px; height: 14px; }
.icon-wall i:nth-child(2) { left: 10px; }
.icon-wall i:nth-child(3) { left: 18px; height: 16px; }
.icon-floor i { position: absolute; left: 1px; width: 24px; height: 5px; background: #c69258; border-radius: 1px; }
.icon-floor i:nth-child(1) { top: 6px; }
.icon-floor i:nth-child(2) { top: 15px; width: 18px; }
.icon-ramp i { position: absolute; inset: 2px; background: linear-gradient(135deg, #c69258 49%, transparent 50%); border-radius: 1px; }
.icon-rocket i { position: absolute; left: 6px; top: 11px; width: 18px; height: 7px; border-radius: 4px 2px 2px 4px; background: #ffdf8a; transform: rotate(-32deg); box-shadow: -7px 4px 0 -1px #ff7b3d; }
.icon-rocket i::before { content: ""; position: absolute; left: -6px; top: 1px; width: 7px; height: 5px; background: #ff5d38; clip-path: polygon(100% 0, 0 50%, 100% 100%); }
.icon-grenade i { position: absolute; left: 6px; top: 7px; width: 15px; height: 15px; border-radius: 50%; background: #76bd72; border: 2px solid #3d7c43; }
.icon-grenade i::after { content: ""; position: absolute; left: 5px; top: -6px; width: 5px; height: 6px; background: #d9d9d9; border-radius: 1px; box-shadow: 5px -2px 0 -1px #888; }
.icon-cluster i { position: absolute; width: 9px; height: 9px; border-radius: 50%; background: #c9a8ff; box-shadow: 0 0 0 2px #6f43c9; }
.icon-cluster i:nth-child(1) { left: 3px; top: 8px; }
.icon-cluster i:nth-child(2) { right: 3px; top: 3px; width: 11px; height: 11px; }
.icon-pick i { position: absolute; inset: 2px; border-radius: 2px; background: linear-gradient(135deg, transparent 46%, #a7bdd8 47%, #dce9ff 53%, transparent 54%); }
.icon-pick i::after { content: ""; position: absolute; left: 3px; top: 11px; width: 20px; height: 4px; border-radius: 4px; background: #8f5b32; transform: rotate(-38deg); }

.turn-actions { margin-left: auto; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; flex: none; width: 158px; }
.icon-btn {
  width: 37px; height: 34px; border-radius: 9px;
  background: var(--panel); border: 1px solid var(--line);
  backdrop-filter: blur(10px);
  color: var(--text); cursor: pointer; pointer-events: auto;
  display: grid; place-items: center;
  transition: background .2s, color .2s, transform .15s;
}
.icon-btn svg { width: 19px; height: 19px; }
.icon-btn:hover { background: rgba(255,255,255,.12); transform: translateY(-1px); }
.icon-btn.muted { color: var(--coral); }
.icon-btn.muted .sound-wave { display: none; }
.end-btn {
  width: 100%;
  border: 2px solid #1a0f2d;
  background: linear-gradient(160deg, var(--yellow), #ffc22c);
  color: var(--ink);
  border-radius: 11px;
  padding: 9px 10px 8px;
  font-family: var(--display);
  letter-spacing: .9px;
  cursor: pointer;
  pointer-events: auto;
  box-shadow: 0 5px 0 #9d6b0a, 0 12px 25px rgba(0,0,0,.3);
  transition: transform .1s, box-shadow .1s, filter .2s;
  display: flex; flex-direction: column; align-items: center; gap: 1px;
}
.end-btn span { font-size: 13px; }
.end-btn small { font-size: 7px; opacity: .6; letter-spacing: 1.2px; }
.end-btn:hover { filter: brightness(1.06); }
.end-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 #9d6b0a; }
.build-limit { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.build-pips { display: flex; gap: 4px; }
.build-pips i { width: 26px; height: 4px; border-radius: 4px; background: rgba(255,255,255,.16); }
.build-pips i.on { background: var(--yellow); box-shadow: 0 0 8px rgba(255,225,74,.5); }

.hint {
  position: absolute;
  left: 50%; bottom: 204px;
  transform: translateX(-50%);
  font-size: 10px;
  letter-spacing: .9px;
  color: rgba(255,255,255,.5);
  text-transform: uppercase;
  background: rgba(10,6,20,.42);
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 99px;
  padding: 5px 12px;
  backdrop-filter: blur(8px);
  white-space: nowrap;
  transition: opacity .3s;
}

/* ---------- start / end overlays ---------- */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  transition: opacity .45s ease, visibility .45s;
}
.start-screen {
  background:
    radial-gradient(circle at 50% 42%, rgba(59, 31, 108, .1), rgba(8, 5, 18, .7) 65%),
    linear-gradient(180deg, rgba(9,5,20,.36), rgba(9,5,20,.22) 42%, rgba(9,5,20,.88));
}
.start-screen::before {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(8,5,18,.94) 0%, transparent 24%, transparent 76%, rgba(8,5,18,.94) 100%);
  pointer-events: none;
}
.start-screen.leaving { opacity: 0; visibility: hidden; }
.start-backdrop {
  position: absolute; inset: 0;
  backdrop-filter: blur(2.5px) saturate(1.08);
  -webkit-backdrop-filter: blur(2.5px) saturate(1.08);
}
.start-content {
  position: relative;
  width: min(920px, 92vw);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  animation: rise .8s cubic-bezier(.2,.8,.2,1) both;
}

.season-badge {
  display: inline-flex; align-items: center; gap: 7px;
  font-family: var(--display); font-size: 9px; letter-spacing: 2.2px;
  color: var(--yellow);
  border: 1px solid rgba(255,225,74,.35);
  background: rgba(255,225,74,.08);
  border-radius: 99px;
  padding: 6px 12px;
  margin-bottom: 16px;
  box-shadow: inset 0 0 18px rgba(255,225,74,.06);
}
.season-badge span { width: 5px; height: 5px; background: var(--yellow); border-radius: 50%; box-shadow: 0 0 10px var(--yellow); }

.logo-wrap { position: relative; line-height: .72; filter: drop-shadow(0 18px 35px rgba(0,0,0,.5)); }
.logo-fort, .logo-worm {
  font-family: var(--display);
  font-size: clamp(76px, 12.4vw, 168px);
  letter-spacing: -0.055em;
  line-height: .78;
  transform: skew(-5deg) scaleX(.94);
}
.logo-fort {
  color: #fff;
  -webkit-text-stroke: 2px rgba(255,255,255,.2);
  text-shadow: 0 4px 0 #4e347c, 0 10px 0 rgba(0,0,0,.28);
}
.logo-worm {
  color: var(--yellow);
  text-shadow: 0 5px 0 #a66312, 0 11px 0 rgba(0,0,0,.32), 0 0 50px rgba(255,225,74,.18);
