}
.tagline em { color: var(--yellow); font-style: normal; font-family: var(--display); letter-spacing: .2px; }
.feature-row { display: flex; align-items: center; justify-content: center; gap: 9px; flex-wrap: wrap; margin-bottom: 28px; }
.feature {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--display); font-size: 8px; letter-spacing: 1.1px;
  color: rgba(255,255,255,.7);
