// Pure helpers shared by the simulation, renderer and tests.

export const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const inverseLerp = (a, b, v) => (a === b ? 0 : (v - a) / (b - a));

export function snap(value, step) {
  return Math.round(value / step) * step;
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function range(rng, min, max) {
  return min + (max - min) * rng();
}

export function pick(rng, list) {
  return list[Math.floor(rng() * list.length) % list.length];
}

export function pointInTriangle(px, py, ax, ay, bx, by, cx, cy) {
  const d1 = (px - bx) * (ay - by) - (ax - bx) * (py - by);
  const d2 = (px - cx) * (by - cy) - (bx - cx) * (py - cy);
  const d3 = (px - ax) * (cy - ay) - (cx - ax) * (py - ay);
  const hasNeg = d1 < 0 || d2 < 0 || d3 < 0;
  const hasPos = d1 > 0 || d2 > 0 || d3 > 0;
  return !(hasNeg && hasPos);
}

export function explosionDamage(distance, radius, maxDamage) {
  if (distance >= radius) return 0;
  const t = clamp(1 - distance / radius, 0, 1);
  // Hits near the centre stay brutal while the edge falls away smoothly.
  return maxDamage * (0.22 + 0.78 * Math.pow(t, 0.72));
}

export function ballisticStep(state, dt, gravity, windAccel) {
  state.vy += gravity * dt;
  state.vx += windAccel * dt;
  state.x += state.vx * dt;
  state.y += state.vy * dt;
  state.life += dt;
  return state;
}

export function formatClock(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

export function circleOverlap(ax, ay, ar, bx, by, br) {
  const dx = ax - bx;
  const dy = ay - by;
  const r = ar + br;
  return dx * dx + dy * dy <= r * r;
}

export function approach(value, target, maxDelta) {
  if (value < target) return Math.min(target, value + maxDelta);
  return Math.max(target, value - maxDelta);
}

export function angleTo(x1, y1, x2, y2) {
  return Math.atan2(y2 - y1, x2 - x1);
}

export function windToAccel(wind) {
  return wind * 1.45;
}

export function makeTrajectoryPreview(start, angle, power, gravity, wind, options = {}) {
  const {
    maxPoints = 95,
    step = 1 / 60,
    maxTime = 4.2,
    solidAt = () => false,
    bounds = { minX: 0, maxX: Infinity, waterY: Infinity },
  } = options;
  const points = [];
  const state = {
    x: start.x,
    y: start.y,
    vx: Math.cos(angle) * power,
    vy: Math.sin(angle) * power,
    life: 0,
  };
  const windAccel = windToAccel(wind);
  for (let i = 0; i < maxPoints; i += 1) {
    ballisticStep(state, step, gravity, windAccel);
    points.push({ x: state.x, y: state.y });
    if (state.life >= maxTime) break;
    if (state.x < bounds.minX || state.x > bounds.maxX || state.y > bounds.waterY) break;
    if (solidAt(state.x, state.y)) break;
  }
  return points;
}

import { clamp, lerp } from './logic.js';

const smoothstep = (edge0, edge1, x) => {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
};

/**
 * Destructible island rendered to an offscreen canvas.
 * Collision reads the canvas' alpha channel, so tunnels, caves and overhangs
 * all behave the same way as the visible terrain.
 */
export class Terrain {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.canvas = document.createElement('canvas');
    this.canvas.width = width;
    this.canvas.height = height;
    this.ctx = this.canvas.getContext('2d', { willReadFrequently: true });
    this.surface = new Float32Array(width);
    this.alpha = null;
    this.scorch = [];
  }

  generate(rng, seed = 1) {
    const { width, height, surface } = this;
    const phase1 = rng() * Math.PI * 2;
    const phase2 = rng() * Math.PI * 2;
    const phase3 = rng() * Math.PI * 2;
    const phase4 = rng() * Math.PI * 2;

    for (let x = 0; x < width; x += 1) {
      const nx = x / width;
      let h = 645
        + 55 * Math.sin(x * 0.0037 + phase1)
        + 26 * Math.sin(x * 0.0103 + phase2)
        + 11 * Math.sin(x * 0.031 + phase3)
        + 6 * Math.sin(x * 0.08 + phase4);

      // Central valley with a gentle bowl.
      h += 34 * Math.exp(-((x - 805) / 145) ** 2);
      // Left plateau.
      h -= 94 * smoothstep(170, 340, x) * (1 - smoothstep(475, 535, x));
      // Right ridge.
      h -= 72 * smoothstep(1030, 1100, x) * (1 - smoothstep(1265, 1375, x));

      // Level the two deployment shelves.
      const leftBlend = 1 - smoothstep(80, 300, Math.abs(x - 290));
      const rightBlend = 1 - smoothstep(80, 300, Math.abs(x - 1310));
      h = lerp(h, 635 + (x - 290) * 0.045, leftBlend * 0.82);
      h = lerp(h, 655 - (x - 1310) * 0.035, rightBlend * 0.82);

      // The island falls away into the sea at both edges.
      const edgeIn = smoothstep(0, 120, x) * smoothstep(0, 120, width - x);
      h += (1 - edgeIn) * 330;
      // Ragged coastal lip.
      h += smoothstep(94, 118, x) * (1 - smoothstep(118, 142, x)) * 22;
      h += smoothstep(width - 142, width - 118, x) * (1 - smoothstep(width - 118, width - 94, x)) * 18;

      surface[x] = h;
    }

    this.drawIsland(rng, seed);
    this.refreshAlpha();
    return this;
  }

  drawIsland(rng, seed) {
    const { ctx, width, height, surface } = this;
    ctx.clearRect(0, 0, width, height);

    const island = new Path2D();
    island.moveTo(0, surface[0]);
    for (let x = 1; x < width; x += 1) island.lineTo(x, surface[x]);
    island.lineTo(width, height);
    island.lineTo(0, height);
    island.closePath();

    // deep rock body
    const body = ctx.createLinearGradient(0, 520, 0, height);
    body.addColorStop(0, '#4f3a4b');
    body.addColorStop(0.2, '#3e2d3d');
    body.addColorStop(0.55, '#302437');
    body.addColorStop(1, '#1c152a');
    ctx.fillStyle = body;
    ctx.fill(island);

    ctx.save();
    ctx.clip(island);

    // Warm topsoil band
    const topsoil = new Path2D();
    topsoil.moveTo(0, surface[0] - 2);
    for (let x = 1; x < width; x += 1) topsoil.lineTo(x, surface[x] - 2);
    for (let x = width - 1; x >= 0; x -= 1) topsoil.lineTo(x, surface[x] + 78 + Math.sin(x * 0.06) * 7);
    topsoil.closePath();
    const soil = ctx.createLinearGradient(0, 520, 0, 760);
    soil.addColorStop(0, '#6e4a30');
    soil.addColorStop(0.35, '#5c3b29');
    soil.addColorStop(1, '#453027');
    ctx.fillStyle = soil;
    ctx.fill(topsoil);

    // sediment strata
    ctx.lineWidth = 3;
    for (let i = 0; i < 9; i += 1) {
      const baseY = 690 + i * 26;
      ctx.strokeStyle = i % 2 ? 'rgba(20,10,28,0.24)' : 'rgba(173,118,82,0.14)';
      ctx.beginPath();
      for (let x = 0; x <= width; x += 18) {
        const y = baseY + Math.sin(x * 0.011 + i * 1.7) * 8 + Math.sin(x * 0.033 + i) * 2.5;
        if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }

    // Rock seams and pebbles
    for (let i = 0; i < 520; i += 1) {
      const x = rng() * width;
      const y = 560 + rng() * (height - 560);
      const size = 1 + rng() * 3.4;
      ctx.fillStyle = rng() > 0.55 ? 'rgba(214,158,124,0.18)' : 'rgba(14,9,24,0.22)';
      ctx.beginPath();
      ctx.ellipse(x, y, size, size * 0.55, rng() * Math.PI, 0, Math.PI * 2);
      ctx.fill();
    }

    // Roots and cracks in the topsoil
    ctx.lineCap = 'round';
    for (let i = 0; i < 34; i += 1) {
      const x = 100 + rng() * (width - 200);
      const y = surface[Math.floor(x)] + 8 + rng() * 36;
      ctx.strokeStyle = `rgba(38,22,20,${0.18 + rng() * 0.24})`;
      ctx.lineWidth = 1 + rng() * 1.6;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.bezierCurveTo(x + 8, y + 10, x - 9, y + 18, x + (rng() - 0.5) * 24, y + 26 + rng() * 18);
      ctx.stroke();
    }

    // Dark lip under the grass line
    ctx.beginPath();
    for (let x = 0; x < width; x += 1) {
      if (x === 0) ctx.moveTo(x, surface[x]); else ctx.lineTo(x, surface[x]);
    }
    ctx.strokeStyle = '#2d2b1e';
    ctx.lineWidth = 13;
    ctx.stroke();

    // Main grass cap
    const grass = ctx.createLinearGradient(0, 540, 0, 700);
    grass.addColorStop(0, '#8eea69');
    grass.addColorStop(0.45, '#55c94f');
    grass.addColorStop(1, '#2d8b3d');
    ctx.beginPath();
    for (let x = 0; x < width; x += 1) {
      if (x === 0) ctx.moveTo(x, surface[x] - 3); else ctx.lineTo(x, surface[x] - 3);
    }
    ctx.strokeStyle = grass;
    ctx.lineWidth = 8;
    ctx.stroke();

    // Highlight rut
    ctx.beginPath();
    for (let x = 0; x < width; x += 1) {
      if (x === 0) ctx.moveTo(x, surface[x] - 6); else ctx.lineTo(x, surface[x] - 6);
    }
    ctx.strokeStyle = 'rgba(196,255,139,0.34)';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.restore();

    // Grass blades and flowers live above the surface, outside the clip.
    for (let x = 8; x < width - 8; x += 4) {
      const sy = surface[x];
      if (sy > 860) continue;
      const blade = 2 + rng() * 8;
      const lean = (rng() - 0.5) * 7;
      ctx.strokeStyle = rng() > 0.7 ? 'rgba(180,255,132,0.8)' : 'rgba(83,205,83,0.72)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(x, sy - 3);
      ctx.quadraticCurveTo(x + lean * 0.4, sy - blade * 0.6, x + lean, sy - blade - 2);
      ctx.stroke();
    }

    for (let i = 0; i < 43; i += 1) {
      const x = 130 + rng() * (width - 260);
      const sy = surface[Math.floor(x)];
      if (sy > 830) continue;
      const hue = rng() > 0.5 ? '#ffe27a' : '#ff9fcb';
      ctx.fillStyle = hue;
      ctx.beginPath();
      ctx.arc(x, sy - 7 - rng() * 6, 1.7, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      ctx.beginPath();
      ctx.arc(x - 0.5, sy - 7.5, 0.6, 0, Math.PI * 2);
      ctx.fill();
    }

    // Deterministic seed speckle so the island feels hand-painted, not tiled.
    ctx.globalAlpha = 0.12;
    for (let i = 0; i < 140; i += 1) {
      const x = (seed * 977 + i * 617) % width;
      const sy = surface[Math.floor(x)];
      ctx.fillStyle = i % 3 ? '#f1c17d' : '#251a2d';
      ctx.fillRect(x, sy + 3 + (i * 13) % 60, 1.5, 1.5);
    }
    ctx.globalAlpha = 1;
  }

  refreshAlpha() {
    const data = this.ctx.getImageData(0, 0, this.width, this.height).data;
    if (!this.alpha) this.alpha = new Uint8Array(this.width * this.height);
    for (let i = 0, p = 3; i < this.alpha.length; i += 1, p += 4) {
      this.alpha[i] = data[p] > 28 ? 1 : 0;
    }
  }

  updateAlpha(x0, y0, x1, y1) {
    const minX = clamp(Math.floor(x0), 0, this.width - 1);
    const minY = clamp(Math.floor(y0), 0, this.height - 1);
    const w = clamp(Math.ceil(x1 - x0), 1, this.width - minX);
    const h = clamp(Math.ceil(y1 - y0), 1, this.height - minY);
    if (!this.alpha) return this.refreshAlpha();
    const data = this.ctx.getImageData(minX, minY, w, h).data;
    for (let row = 0; row < h; row += 1) {
      for (let col = 0; col < w; col += 1) {
        const a = data[(row * w + col) * 4 + 3];
        this.alpha[(minY + row) * this.width + minX + col] = a > 28 ? 1 : 0;
      }
    }
  }

  solidAt(x, y) {
    if (!this.alpha || x < 0 || y < 0 || x >= this.width || y >= this.height) return false;
    return this.alpha[(y | 0) * this.width + (x | 0)] === 1;
  }

  /** First solid pixel in a column at or below fromY. */
  groundBelow(x, fromY = 0, maxY = this.height) {
    if (x < 0 || x >= this.width) return null;
    const col = x | 0;
    const start = clamp(Math.ceil(fromY), 0, this.height - 1);
    const end = clamp(Math.ceil(maxY), 0, this.height - 1);
    for (let y = start; y <= end; y += 2) {
      if (this.alpha[y * this.width + col]) return y;
    }
    return null;
  }

  surfaceY(x) {
    return this.groundBelow(x, 0, this.height) ?? this.height;
  }

  destroyCircle(cx, cy, radius, rng = Math.random) {
    const ctx = this.ctx;
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath();
    const lobes = 9;
    for (let i = 0; i < lobes; i += 1) {
      const a = (i / lobes) * Math.PI * 2;
      const rr = radius * (0.72 + rng() * 0.24);
      const x = cx + Math.cos(a) * radius * 0.18;
      const y = cy + Math.sin(a) * radius * 0.18;
      ctx.moveTo(x + rr, y);
      ctx.arc(x, y, rr, 0, Math.PI * 2);
    }
    ctx.fill();
    ctx.restore();

    // A charred rim sells the heat without turning the hole into a solid ring.
    ctx.save();
    ctx.globalCompositeOperation = 'source-atop';
    const rim = ctx.createRadialGradient(cx, cy, radius * 0.7, cx, cy, radius * 1.18);
    rim.addColorStop(0, 'rgba(18,8,18,0)');
    rim.addColorStop(0.68, 'rgba(22,9,18,0.18)');
    rim.addColorStop(1, 'rgba(8,4,12,0)');
    ctx.fillStyle = rim;
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 1.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    const pad = radius * 1.5 + 8;
    this.updateAlpha(cx - pad, cy - pad, cx + pad, cy + pad);
    this.scorch.push({ x: cx, y: cy, r: radius, life: 1 });
    if (this.scorch.length > 60) this.scorch.shift();
  }

  carveMelee(x, y, radius = 14) {
    const ctx = this.ctx;
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath();
    ctx.ellipse(x, y, radius, radius * 0.62, 0.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    this.updateAlpha(x - radius - 2, y - radius - 2, x + radius + 2, y + radius + 2);
  }

  draw(ctx) {
    ctx.drawImage(this.canvas, 0, 0);
  }
}

/**
 * Tiny procedural audio engine. No samples, no network — every boom is
 * generated from oscillators and shaped noise so the game stays self-contained.
 */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.ambientGain = null;
    this.muted = false;
    this.started = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.42;
    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -16;
    compressor.knee.value = 20;
    compressor.ratio.value = 9;
    this.master.connect(compressor).connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2.4);
    this.startAmbient();
    this.started = true;
  }

  makeNoise(seconds) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    return buffer;
  }

  startAmbient() {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 310;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.018;
    const lfo = this.ctx.createOscillator();
    const lfoGain = this.ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 0.01;
    lfo.connect(lfoGain).connect(gain.gain);
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    lfo.start();
    this.ambientGain = gain;
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(muted ? 0 : 0.42, now, 0.04);
  }

  toggleMute() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  tone({ freq = 220, endFreq = freq, type = 'sine', dur = 0.2, gain = 0.18, delay = 0, attack = 0.006 }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const env = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(1, endFreq), t + dur);
    env.gain.setValueAtTime(0.0001, t);
    env.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    env.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(env).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.05);
  }

  noise({ dur = 0.4, gain = 0.2, freq = 900, q = 0.7, type = 'lowpass', delay = 0, sweepTo = null }) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.Q.value = q;
    filter.frequency.setValueAtTime(freq, t);
    if (sweepTo) filter.frequency.exponentialRampToValueAtTime(Math.max(30, sweepTo), t + dur);
    const env = this.ctx.createGain();
    env.gain.setValueAtTime(0.0001, t);
    env.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    env.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(env).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  play(name, intensity = 1) {
    if (!this.ctx || this.muted) return;
    switch (name) {
      case 'ui':
        this.tone({ freq: 560, endFreq: 720, type: 'square', dur: 0.07, gain: 0.035 });
        break;
      case 'select':
        this.tone({ freq: 380, endFreq: 560, type: 'triangle', dur: 0.09, gain: 0.06 });
        break;
      case 'deny':
        this.tone({ freq: 160, endFreq: 110, type: 'sawtooth', dur: 0.16, gain: 0.05 });
        break;
      case 'deploy':
        this.tone({ freq: 90, endFreq: 180, type: 'sawtooth', dur: 0.5, gain: 0.09 });
        this.tone({ freq: 300, endFreq: 600, type: 'triangle', dur: 0.4, gain: 0.05, delay: 0.15 });
        this.tone({ freq: 600, endFreq: 900, type: 'square', dur: 0.22, gain: 0.035, delay: 0.32 });
        break;
      case 'shoot':
        this.noise({ dur: 0.5, gain: 0.34, freq: 1600, sweepTo: 180 });
        this.tone({ freq: 170, endFreq: 48, type: 'sawtooth', dur: 0.42, gain: 0.16 });
        this.noise({ dur: 0.3, gain: 0.08, freq: 3200, type: 'highpass' });
        break;
      case 'launch':
        this.noise({ dur: 0.7, gain: 0.13, freq: 600, sweepTo: 2200, type: 'bandpass', q: 1.4 });
        break;
      case 'explode':
        this.noise({ dur: 0.9 + intensity * 0.25, gain: 0.5, freq: 1100, sweepTo: 60 });
        this.tone({ freq: 130, endFreq: 28, type: 'sine', dur: 0.85, gain: 0.34 });
        this.tone({ freq: 74, endFreq: 22, type: 'triangle', dur: 1.15, gain: 0.24, delay: 0.03 });
        this.noise({ dur: 0.15, gain: 0.14, freq: 4200, type: 'highpass' });
        break;
      case 'build':
        this.tone({ freq: 240, endFreq: 120, type: 'square', dur: 0.09, gain: 0.07 });
        this.noise({ dur: 0.08, gain: 0.12, freq: 1300, type: 'bandpass', q: 1.2 });
        break;
      case 'buildMetal':
        this.tone({ freq: 680, endFreq: 430, type: 'triangle', dur: 0.18, gain: 0.07 });
        this.tone({ freq: 1020, endFreq: 720, type: 'sine', dur: 0.25, gain: 0.04, delay: 0.02 });
        break;
      case 'harvest':
        this.noise({ dur: 0.15, gain: 0.17, freq: 700, type: 'bandpass', q: 1.6 });
        this.tone({ freq: 310, endFreq: 210, type: 'sawtooth', dur: 0.12, gain: 0.06 });
        break;
      case 'hurt':
        this.tone({ freq: 380, endFreq: 120, type: 'sawtooth', dur: 0.25, gain: 0.09 });
        break;
      case 'jump':
        this.tone({ freq: 210, endFreq: 410, type: 'triangle', dur: 0.13, gain: 0.04 });
        break;
      case 'land':
        this.tone({ freq: 110, endFreq: 65, type: 'sine', dur: 0.1, gain: 0.06 });
        break;
      case 'bounce':
        this.tone({ freq: 300, endFreq: 190, type: 'square', dur: 0.08, gain: 0.035 });
        break;
      case 'splash':
        this.noise({ dur: 0.5, gain: 0.18, freq: 1300, sweepTo: 420, type: 'bandpass', q: 0.8 });
        break;
      case 'turn':
        this.tone({ freq: 440, type: 'triangle', dur: 0.13, gain: 0.04 });
        this.tone({ freq: 660, type: 'triangle', dur: 0.18, gain: 0.04, delay: 0.09 });
        break;
      case 'victory':
        [392, 523, 659, 784, 1046].forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.36, gain: 0.075, delay: i * 0.12 }));
        this.noise({ dur: 0.7, gain: 0.05, freq: 6200, type: 'highpass', delay: 0.5 });
        break;
      case 'defeat':
        [330, 294, 247, 196].forEach((f, i) => this.tone({ freq: f, endFreq: f * 0.94, type: 'sawtooth', dur: 0.5, gain: 0.05, delay: i * 0.17 }));
        break;
      case 'tick':
        this.tone({ freq: 780, type: 'square', dur: 0.025, gain: 0.018 });
        break;
      case 'charge':
        this.tone({ freq: 220, endFreq: 560, type: 'sine', dur: 0.5, gain: 0.035 });
        break;
      default:
        break;
    }
  }
}

import { clamp, range } from './logic.js';

const TAU = Math.PI * 2;

function particle(props) {
  return {
    x: 0, y: 0, vx: 0, vy: 0,
    life: 1, maxLife: 1,
    size: 4, endSize: 0,
    color: '#fff', gravity: 0, drag: 0.99,
    shape: 'circle', rotation: 0, spin: 0,
    additive: false, glow: 0, alpha: 1,
    ...props,
  };
}

export class Particles {
  constructor() {
    this.items = [];
    this.shockwaves = [];
    this.flashes = [];
    this.decals = [];
  }

  clear() {
    this.items.length = 0;
    this.shockwaves.length = 0;
    this.flashes.length = 0;
  }

  add(p) {
    if (this.items.length > 900) this.items.shift();
    this.items.push(particle(p));
  }

  flash(x, y, radius, color = '#ffcf7a') {
    this.flashes.push({ x, y, radius, life: 0.22, maxLife: 0.22, color });
  }

  shockwave(x, y, radius, color = '255,220,140') {
    this.shockwaves.push({ x, y, radius, life: 0.55, maxLife: 0.55, color });
  }

  explosion(x, y, radius, palette = {}) {
    const dirt = palette.dirt ?? ['#6f4a31', '#55351f', '#8a5f3c'];
    const grass = palette.grass ?? ['#65d354', '#2f9d45'];
    const count = Math.round(clamp(radius * 0.85, 26, 74));
    this.flash(x, y, radius * 2.5);
    this.shockwave(x, y, radius * 0.5, '255,226,160');
    this.shockwave(x, y, radius * 0.25, '255,255,230');

    for (let i = 0; i < 18; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 20, radius * 2.8);
      this.add({
        x: x + Math.cos(a) * radius * 0.36,
        y: y + Math.sin(a) * radius * 0.36,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 20,
        life: range(Math.random, 0.35, 0.85),
        size: range(Math.random, radius * 0.28, radius * 0.7),
        endSize: range(Math.random, radius * 0.5, radius * 1.1),
        color: i % 3 === 0 ? '#fff4bd' : i % 3 === 1 ? '#ffae3d' : '#ff6b32',
        shape: 'circle', drag: 0.92, gravity: -30,
        additive: true, glow: 1,
      });
    }

    for (let i = 0; i < count; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 70, radius * 5.2);
      const isDirt = Math.random() > 0.22;
      this.add({
        x: x + Math.cos(a) * radius * 0.4,
        y: y + Math.sin(a) * radius * 0.4,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - range(Math.random, 30, 140),
        life: range(Math.random, 0.55, 1.45),
        size: range(Math.random, 2, isDirt ? 7 : 4),
        endSize: range(Math.random, 0.5, 2),
        color: isDirt
          ? (Math.random() > 0.5 ? dirt : grass)[Math.floor(Math.random() * 3) % (Math.random() > 0.5 ? dirt : grass).length]
          : (Math.random() > 0.5 ? '#ffd66b' : '#ff8a3d'),
        shape: isDirt ? 'rect' : 'spark',
        gravity: isDirt ? 820 : 60,
        drag: isDirt ? 0.995 : 0.96,
        rotation: Math.random() * TAU,
        spin: range(Math.random, -9, 9),
        additive: !isDirt,
        glow: isDirt ? 0 : 0.7,
      });
    }

    for (let i = 0; i < 16; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 18, radius * 1.1);
      this.add({
        x: x + Math.cos(a) * radius * 0.3,
        y: y + Math.sin(a) * radius * 0.3,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - range(Math.random, 15, 60),
        life: range(Math.random, 1.2, 2.6),
        size: range(Math.random, radius * 0.45, radius * 0.95),
        endSize: range(Math.random, radius * 1.15, radius * 2.2),
        color: Math.random() > 0.5 ? '#241a2b' : '#4e3c47',
        shape: 'smoke', drag: 0.97, gravity: -7, alpha: 0.55,
      });
    }
  }

  muzzle(x, y, angle, scale = 1) {
    for (let i = 0; i < 13; i += 1) {
      const a = angle + range(Math.random, -0.4, 0.4);
      const speed = range(Math.random, 100, 480) * scale;
      this.add({
        x, y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed,
        life: range(Math.random, 0.1, 0.34),
        size: range(Math.random, 2, 7) * scale,
        endSize: 0,
        color: i % 3 ? '#ffd66e' : '#fff8cf',
        shape: 'spark', drag: 0.93, gravity: 60, additive: true, glow: 1,
      });
    }
    this.add({
      x, y,
      vx: Math.cos(angle) * 40,
      vy: Math.sin(angle) * 40,
      life: 0.55, size: 9 * scale, endSize: 38 * scale,
      color: '#32263a', shape: 'smoke', drag: 0.94, alpha: 0.45, gravity: -15,
    });
  }

  rocketTrail(x, y, angle) {
    const a = angle + Math.PI + range(Math.random, -0.35, 0.35);
    this.add({
      x: x + Math.cos(a) * 10,
      y: y + Math.sin(a) * 10,
      vx: Math.cos(a) * range(Math.random, 10, 60),
      vy: Math.sin(a) * range(Math.random, 10, 60),
      life: range(Math.random, 0.2, 0.55),
      size: range(Math.random, 2, 5),
      endSize: range(Math.random, 7, 16),
      color: Math.random() > 0.4 ? '#5b4b5f' : '#c9a98d',
      shape: 'smoke', drag: 0.95, gravity: -18, alpha: 0.38,
    });
    if (Math.random() > 0.35) {
      this.add({
        x: x + Math.cos(a) * 8,
        y: y + Math.sin(a) * 8,
        vx: Math.cos(a) * 40,
        vy: Math.sin(a) * 40,
        life: 0.14, size: 2.6, endSize: 0,
        color: Math.random() > 0.5 ? '#ffe9a3' : '#ff9c3e',
        shape: 'spark', additive: true, glow: 1, drag: 0.9,
      });
    }
  }

  grenadeTrail(x, y) {
    if (Math.random() > 0.5) {
      this.add({
        x, y,
        vx: range(Math.random, -12, 12),
        vy: range(Math.random, -12, 12),
        life: 0.22, size: 1.6, endSize: 4,
        color: '#dfe9ff', shape: 'smoke', alpha: 0.24, drag: 0.94,
      });
    }
  }

  buildBurst(x, y, material, good = true) {
    const colors = material === 'brick'
      ? ['#d46b5b', '#a84b42', '#f59b7d']
      : material === 'metal'
        ? ['#a9c0dc', '#6d84a7', '#e6f3ff']
        : ['#c99152', '#8f5c2d', '#e8b878'];
    for (let i = 0; i < 24; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 20, 180);
      this.add({
        x, y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 60,
        life: range(Math.random, 0.3, 0.85),
        size: range(Math.random, 2, 5.2),
        endSize: 0.5,
        color: colors[Math.floor(Math.random() * colors.length)],
        shape: 'rect', gravity: 720, drag: 0.995,
        rotation: Math.random() * TAU, spin: range(Math.random, -8, 8),
      });
    }
    this.shockwave(x, y, 8, good ? '255,232,130' : '255,110,110');
    for (let i = 0; i < 6; i += 1) {
      this.add({
        x, y,
        vx: range(Math.random, -50, 50),
        vy: range(Math.random, -80, 10),
        life: 0.5, size: 10, endSize: 28,
        color: '#3d3048', shape: 'smoke', alpha: 0.3, drag: 0.95,
      });
    }
  }

  harvest(x, y, colors = ['#7edc64', '#5a3820']) {
    for (let i = 0; i < 16; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 40, 200);
      this.add({
        x, y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 80,
        life: range(Math.random, 0.35, 0.9),
        size: range(Math.random, 1.5, 4.5),
        endSize: 0.6,
        color: colors[Math.floor(Math.random() * colors.length)],
        shape: Math.random() > 0.5 ? 'rect' : 'spark',
        gravity: 640, drag: 0.995, rotation: Math.random() * TAU,
        spin: range(Math.random, -8, 8), additive: Math.random() > 0.6,
      });
    }
  }

  hurt(x, y, color = '#ff6b72') {
    for (let i = 0; i < 12; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 30, 170);
      this.add({
        x, y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 40,
        life: range(Math.random, 0.25, 0.65),
        size: range(Math.random, 2, 6),
        endSize: 0,
        color: i % 2 ? color : '#fff0c9',
        shape: 'spark', gravity: 510, drag: 0.98, additive: true, glow: 0.7,
      });
    }
  }

  death(x, y, color) {
    this.flash(x, y, 140, '#ffe2a0');
    this.shockwave(x, y, 16, '255,210,120');
    for (let i = 0; i < 40; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 50, 340);
      this.add({
        x, y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 90,
        life: range(Math.random, 0.6, 1.5),
        size: range(Math.random, 2, 7),
        endSize: 0,
        color: Math.random() > 0.35 ? color : '#ffe6a8',
        shape: Math.random() > 0.4 ? 'spark' : 'circle',
        gravity: 420, drag: 0.985,
        additive: Math.random() > 0.4, glow: 0.8,
      });
    }
    for (let i = 0; i < 12; i += 1) {
      this.add({
        x, y,
        vx: range(Math.random, -80, 80),
        vy: range(Math.random, -120, 20),
        life: range(Math.random, 0.8, 1.8),
        size: range(Math.random, 10, 24),
        endSize: range(Math.random, 30, 60),
        color: '#453447', shape: 'smoke', alpha: 0.4, drag: 0.96,
      });
    }
  }

  splash(x, y) {
    for (let i = 0; i < 22; i += 1) {
      const a = -Math.PI / 2 + range(Math.random, -0.9, 0.9);
      const speed = range(Math.random, 40, 230);
      this.add({
        x, y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed,
        life: range(Math.random, 0.3, 0.9),
        size: range(Math.random, 2, 7),
        endSize: 0,
        color: Math.random() > 0.4 ? '#a8f7ff' : '#e4feff',
        shape: 'circle', gravity: 620, drag: 0.99,
      });
    }
    this.shockwave(x, y, 5, '140,235,255');
  }

  confetti(x, y, count = 80) {
    const colors = ['#ffe14a', '#9d63ff', '#58eeff', '#ff6d72', '#6df08a', '#fff'];
    for (let i = 0; i < count; i += 1) {
      const a = Math.random() * TAU;
      const speed = range(Math.random, 80, 420);
      this.add({
        x: x + range(Math.random, -150, 150),
        y: y + range(Math.random, -40, 40),
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 250,
        life: range(Math.random, 1.2, 2.8),
        size: range(Math.random, 2, 5),
        endSize: 1,
        color: colors[Math.floor(Math.random() * colors.length)],
        shape: 'rect', gravity: 380, drag: 0.985,
        rotation: Math.random() * TAU, spin: range(Math.random, -12, 12),
      });
    }
  }

  dust(x, y, amount = 8) {
    for (let i = 0; i < amount; i += 1) {
      this.add({
        x: x + range(Math.random, -10, 10),
        y: y + range(Math.random, -4, 4),
        vx: range(Math.random, -36, 36),
        vy: range(Math.random, -30, -4),
        life: range(Math.random, 0.35, 0.85),
        size: range(Math.random, 3, 7),
        endSize: range(Math.random, 12, 24),
        color: '#b78d68', shape: 'smoke', drag: 0.94, alpha: 0.28,
      });
    }
  }

  update(dt, terrain) {
    for (let i = this.items.length - 1; i >= 0; i -= 1) {
      const p = this.items[i];
      p.life -= dt;
      if (p.life <= 0) { this.items.splice(i, 1); continue; }
      p.vy += p.gravity * dt;
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vy *= Math.pow(p.drag, dt * 60);
      const nx = p.x + p.vx * dt;
      const ny = p.y + p.vy * dt;
      if (terrain && (p.shape === 'rect' || p.shape === 'circle') && p.gravity > 200) {
        if (terrain.solidAt(nx, ny)) {
          p.vy *= -0.32;
          p.vx *= 0.55;
          p.y = p.y - 1;
        } else {
          p.x = nx;
          p.y = ny;
        }
      } else {
        p.x = nx;
        p.y = ny;
      }
      p.rotation += p.spin * dt;
    }

    for (let i = this.shockwaves.length - 1; i >= 0; i -= 1) {
      const s = this.shockwaves[i];
      s.life -= dt;
      if (s.life <= 0) this.shockwaves.splice(i, 1);
    }
    for (let i = this.flashes.length - 1; i >= 0; i -= 1) {
      const f = this.flashes[i];
      f.life -= dt;
      if (f.life <= 0) this.flashes.splice(i, 1);
    }
  }

  draw(ctx) {
    for (const s of this.shockwaves) {
      const t = 1 - s.life / s.maxLife;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = `rgba(${s.color},${(1 - t) * 0.7})`;
      ctx.lineWidth = Math.max(0.5, 6 * (1 - t));
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.radius + t * 150, 0, TAU);
      ctx.stroke();
      ctx.restore();
    }

    const normal = [];
    const additive = [];
    for (const p of this.items) (p.additive ? additive : normal).push(p);

    for (const p of normal) {
      const lifeT = clamp(p.life / p.maxLife, 0, 1);
      const alpha = p.alpha * Math.min(1, lifeT * 2.4);
      const size = Math.max(0.2, p.size + (p.endSize - p.size) * (1 - lifeT));
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.translate(p.x, p.y);
      if (p.rotation) ctx.rotate(p.rotation);
      if (p.shape === 'smoke') {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, size);
        grad.addColorStop(0, p.color);
        grad.addColorStop(1, 'rgba(20,14,28,0)');
        ctx.fillStyle = grad;
      } else {
        ctx.fillStyle = p.color;
      }
      if (p.shape === 'rect') {
        ctx.fillRect(-size / 2, -size / 2, size, size * 0.72);
      } else if (p.shape === 'spark') {
        ctx.beginPath();
        ctx.ellipse(0, 0, size * 1.7, size * 0.48, 0, 0, TAU);
        ctx.fill();
      } else {
        ctx.beginPath();
        ctx.arc(0, 0, size, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }

    if (additive.length) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (const p of additive) {
        const lifeT = clamp(p.life / p.maxLife, 0, 1);
        const size = Math.max(0.2, p.size + (p.endSize - p.size) * (1 - lifeT));
        ctx.globalAlpha = p.alpha * Math.min(1, lifeT * 2.4);
        if (p.glow) {
          const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, size * 3.2);
          grad.addColorStop(0, p.color);
          grad.addColorStop(0.32, p.color);
          grad.addColorStop(1, 'rgba(0,0,0,0)');
          ctx.fillStyle = grad;
          ctx.beginPath();
          ctx.arc(p.x, p.y, size * 3.2, 0, TAU);
          ctx.fill();
        }
        ctx.fillStyle = p.color;
        ctx.beginPath();
        if (p.shape === 'spark') {
          ctx.ellipse(p.x, p.y, size * 2.2, size * 0.55, Math.atan2(p.vy, p.vx), 0, TAU);
        } else {
          ctx.arc(p.x, p.y, size, 0, TAU);
        }
        ctx.fill();
      }
      ctx.restore();
    }

    for (const f of this.flashes) {
      const t = f.life / f.maxLife;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const grad = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.radius);
      grad.addColorStop(0, `rgba(255,245,210,${0.5 * t})`);
      grad.addColorStop(0.35, `rgba(255,170,80,${0.18 * t})`);
      grad.addColorStop(1, 'rgba(255,90,40,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.radius, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }
}

import { clamp, lerp, mulberry32, range } from './logic.js';

const TAU = Math.PI * 2;
const WATER_Y = 868;
const FONT = '"Arial Black", "DejaVu Sans", sans-serif';

const MATERIALS = {
  wood: { base: '#b97a3f', light: '#e4ab68', dark: '#74451f', edge: '#4d2d17', glow: '255,212,130' },
  brick: { base: '#c85e51', light: '#ef8a79', dark: '#7e322e', edge: '#4d1e22', glow: '255,148,128' },
  metal: { base: '#8097b7', light: '#cfe3f8', dark: '#445a79', edge: '#273850', glow: '175,220,255' },
};

function roundRectPath(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function withAlpha(hex, alpha) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${alpha})`;
}

export class Renderer {
  constructor(canvas, game) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.game = game;
    this.width = 1600;
    this.height = 900;
    this.scale = 1;
    this.offsetX = 0;
    this.offsetY = 0;
    this.dpr = 1;
    this.time = 0;
    this.rng = mulberry32(7331);
    this.clouds = [];
    this.islands = [];
    this.mountains = [];
    this.birds = [];
    this.sparkles = [];
    this.embers = [];
    this.rays = [];
    this.initScene();
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }

  initScene() {
    const rng = this.rng;
    for (let i = 0; i < 12; i += 1) {
      this.clouds.push({
        x: rng() * 1900 - 150,
        y: 70 + rng() * 330,
        s: 0.5 + rng() * 1.35,
        alpha: 0.08 + rng() * 0.13,
        speed: 3 + rng() * 9,
      });
    }
    for (let i = 0; i < 5; i += 1) {
      this.islands.push({
        x: 100 + rng() * 1450,
        y: 155 + rng() * 210,
        s: 0.35 + rng() * 0.85,
        phase: rng() * TAU,
        drift: 4 + rng() * 7,
      });
    }
    for (let layer = 0; layer < 3; layer += 1) {
      const points = [];
      const baseY = 540 + layer * 48;
      const step = 38 + layer * 10;
      for (let x = -100; x <= 1720; x += step) {
        const y = baseY + Math.sin(x * (0.004 + layer * 0.002) + layer * 3) * (24 + layer * 14)
          + Math.sin(x * 0.017 + layer) * (8 + layer * 6);
        points.push({ x, y });
      }
      this.mountains.push({ points, layer });
    }
    for (let i = 0; i < 5; i += 1) {
      this.birds.push({ x: rng() * 1600, y: 150 + rng() * 240, s: 0.5 + rng() * 0.6, phase: rng() * TAU, speed: 8 + rng() * 8 });
    }
    for (let i = 0; i < 65; i += 1) {
      this.sparkles.push({ x: 50 + rng() * 1500, y: WATER_Y + rng() * 26, phase: rng() * TAU, speed: 0.5 + rng() });
    }
    for (let i = 0; i < 24; i += 1) {
      this.embers.push({ x: rng() * 1600, y: 400 + rng() * 430, phase: rng() * TAU, speed: 0.3 + rng() * 0.9, s: 0.7 + rng() * 1.8 });
    }
    for (let i = 0; i < 4; i += 1) {
      this.rays.push({ x: 1080 + rng() * 180, w: 40 + rng() * 90, alpha: 0.02 + rng() * 0.035, phase: rng() * TAU });
    }
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const vw = Math.max(1, rect.width || window.innerWidth);
    const vh = Math.max(1, rect.height || window.innerHeight);
    this.viewWidth = vw;
    this.viewHeight = vh;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(vw * this.dpr);
    this.canvas.height = Math.round(vh * this.dpr);
    this.scale = Math.min(vw / this.width, vh / this.height);
    this.offsetX = (vw - this.width * this.scale) / 2;
    this.offsetY = (vh - this.height * this.scale) / 2;
  }

  screenToWorld(clientX, clientY) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (clientX - rect.left - this.offsetX) / this.scale,
      y: (clientY - rect.top - this.offsetY) / this.scale,
    };
  }

  worldToScreen(x, y) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: x * this.scale + this.offsetX + rect.left,
      y: y * this.scale + this.offsetY + rect.top,
    };
  }

  draw(game, dt) {
    this.time += dt;
    const ctx = this.ctx;
    const t = this.time;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.viewWidth, this.viewHeight);

    const bg = ctx.createLinearGradient(0, 0, 0, this.viewHeight);
    bg.addColorStop(0, '#0a0716');
    bg.addColorStop(0.5, '#120c24');
    bg.addColorStop(1, '#1a102c');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, this.viewWidth, this.viewHeight);

    const shake = game.shake || 0;
    const shakeX = Math.sin(t * 92) * shake * 9 + Math.sin(t * 47) * shake * 4;
    const shakeY = Math.cos(t * 83) * shake * 7 + Math.sin(t * 61) * shake * 3;

    ctx.save();
    ctx.translate(this.offsetX + shakeX, this.offsetY + shakeY);
    ctx.scale(this.scale, this.scale);
    ctx.beginPath();
    ctx.rect(-2, -2, this.width + 4, this.height + 4);
    ctx.clip();

    this.drawSky(ctx, t, game);
    this.drawSea(ctx, t);
    this.drawMountains(ctx, t);
    this.drawFloatingIslands(ctx, t);
    this.drawClouds(ctx, t);
    this.drawBirds(ctx, t);

    if (game.terrain) game.terrain.draw(ctx);
    this.drawBuildings(ctx, game, t);
    this.drawWormShadows(ctx, game);
    this.drawWorms(ctx, game, t);
    this.drawProjectiles(ctx, game, t);
    game.particles.draw(ctx);
    this.drawAim(ctx, game, t);
    this.drawWater(ctx, t);
    this.drawAtmosphere(ctx, t);
    this.drawStorm(ctx, game, t);

    ctx.restore();

    this.drawOverlayEffects(ctx, game, t);
    this.drawLetterbox(ctx, t);
  }

  drawSky(ctx, t, game) {
    const sky = ctx.createLinearGradient(0, 0, 0, 760);
    sky.addColorStop(0, '#171239');
    sky.addColorStop(0.28, '#372364');
    sky.addColorStop(0.55, '#7d3f7a');
    sky.addColorStop(0.76, '#e67676');
    sky.addColorStop(0.9, '#ffab6f');
    sky.addColorStop(1, '#ffd294');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, this.width, 790);

    // Sun
    const sunX = 1172;
    const sunY = 292;
    const glow = ctx.createRadialGradient(sunX, sunY, 8, sunX, sunY, 310);
    glow.addColorStop(0, 'rgba(255,245,198,0.95)');
    glow.addColorStop(0.12, 'rgba(255,216,122,0.6)');
    glow.addColorStop(0.4, 'rgba(255,151,103,0.18)');
    glow.addColorStop(1, 'rgba(255,110,80,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(sunX - 320, sunY - 320, 640, 640);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const disc = ctx.createRadialGradient(sunX - 12, sunY - 16, 4, sunX, sunY, 74);
    disc.addColorStop(0, '#fffbe3');
    disc.addColorStop(0.55, '#ffe9a8');
    disc.addColorStop(1, '#ffbf78');
    ctx.fillStyle = disc;
    ctx.beginPath();
    ctx.arc(sunX, sunY, 72, 0, TAU);
    ctx.fill();
    ctx.restore();

    // Sun rays
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const ray of this.rays) {
      const sway = Math.sin(t * 0.11 + ray.phase) * 0.06;
      ctx.save();
      ctx.translate(sunX, sunY);
      ctx.rotate(-0.95 + sway);
      const grad = ctx.createLinearGradient(0, 0, 0, 780);
      grad.addColorStop(0, `rgba(255,236,180,${ray.alpha})`);
      grad.addColorStop(0.55, `rgba(255,184,128,${ray.alpha * 0.55})`);
      grad.addColorStop(1, 'rgba(255,150,100,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(ray.x - sunX - ray.w / 2, 0, ray.w, 820);
      ctx.restore();
    }
    ctx.restore();

    // High haze
    const haze = ctx.createLinearGradient(0, 360, 0, 760);
    haze.addColorStop(0, 'rgba(255,153,130,0)');
    haze.addColorStop(0.7, 'rgba(255,155,116,0.16)');
    haze.addColorStop(1, 'rgba(255,195,138,0.1)');
    ctx.fillStyle = haze;
    ctx.fillRect(0, 360, this.width, 400);

    // Distant storm bank on the right
    ctx.save();
    const storm = ctx.createLinearGradient(1520, 140, 1350, 540);
    storm.addColorStop(0, 'rgba(72,39,134,0.3)');
    storm.addColorStop(0.6, 'rgba(105,45,145,0.12)');
    storm.addColorStop(1, 'rgba(120,60,150,0)');
    ctx.fillStyle = storm;
    ctx.beginPath();
    ctx.ellipse(1570, 300, 260, 320, -0.22, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 0.2;
    ctx.strokeStyle = '#c7a5ff';
    ctx.lineWidth = 2;
    for (let i = 0; i < 3; i += 1) {
      ctx.beginPath();
      ctx.arc(1520 - i * 22, 330 + i * 12, 130 + i * 40, -1.3, 1.1);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawClouds(ctx, t) {
    for (const c of this.clouds) {
      const x = ((c.x + t * c.speed) % 1950) - 160;
      ctx.save();
      ctx.globalAlpha = c.alpha;
      const grad = ctx.createLinearGradient(x, c.y - 60 * c.s, x, c.y + 45 * c.s);
      grad.addColorStop(0, '#ffd8c0');
      grad.addColorStop(0.55, '#f09aaf');
      grad.addColorStop(1, '#975b8e');
      ctx.fillStyle = grad;
      const s = c.s;
      ctx.beginPath();
      ctx.ellipse(x, c.y, 110 * s, 18 * s, 0, 0, TAU);
      ctx.ellipse(x - 48 * s, c.y + 3 * s, 48 * s, 16 * s, 0.1, 0, TAU);
      ctx.ellipse(x + 42 * s, c.y - 6 * s, 55 * s, 20 * s, -0.08, 0, TAU);
      ctx.ellipse(x - 12 * s, c.y - 13 * s, 54 * s, 22 * s, 0.04, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  drawMountains(ctx, t) {
    const palettes = [
      { top: '#4b3168', bottom: '#2e1e46', alpha: 0.62, offset: 30 },
      { top: '#38264f', bottom: '#241737', alpha: 0.82, offset: 12 },
      { top: '#251a37', bottom: '#181025', alpha: 0.95, offset: 0 },
    ];
    this.mountains.forEach((m) => {
      const p = palettes[m.layer];
      const points = m.points;
      ctx.save();
      ctx.globalAlpha = p.alpha;
      const grad = ctx.createLinearGradient(0, 480, 0, 760);
      grad.addColorStop(0, p.top);
      grad.addColorStop(1, p.bottom);
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(points[0].x, 820);
      for (const point of points) {
        ctx.lineTo(point.x, point.y + p.offset - Math.sin(t * 0.03 + m.layer) * 1.2);
      }
      ctx.lineTo(points[points.length - 1].x, 820);
      ctx.closePath();
      ctx.fill();

      // atmospheric rim on the closest ridge
      if (m.layer === 2) {
        ctx.globalAlpha = 0.22;
        ctx.strokeStyle = '#ffb58a';
        ctx.lineWidth = 2;
        ctx.beginPath();
        points.forEach((point, i) => {
          if (i === 0) ctx.moveTo(point.x, point.y + p.offset);
          else ctx.lineTo(point.x, point.y + p.offset);
        });
        ctx.stroke();
      }
      ctx.restore();
    });
  }

  drawFloatingIslands(ctx, t) {
    for (const island of this.islands) {
      const x = island.x + Math.sin(t * 0.09 + island.phase) * island.drift;
      const y = island.y + Math.cos(t * 0.13 + island.phase) * 3;
      const s = island.s;
      ctx.save();
      ctx.translate(x, y);
      ctx.globalAlpha = 0.5 + s * 0.28;

      const rock = ctx.createLinearGradient(0, 0, 0, 90 * s);
      rock.addColorStop(0, '#664272');
      rock.addColorStop(0.5, '#3e2850');
      rock.addColorStop(1, 'rgba(38,23,55,0)');
      ctx.fillStyle = rock;
      ctx.beginPath();
      ctx.moveTo(-48 * s, 0);
      ctx.quadraticCurveTo(-40 * s, 28 * s, -12 * s, 60 * s);
      ctx.quadraticCurveTo(0, 78 * s, 8 * s, 58 * s);
      ctx.quadraticCurveTo(34 * s, 26 * s, 50 * s, 0);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#78a85f';
      ctx.beginPath();
      ctx.ellipse(0, 0, 51 * s, 10 * s, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#a8d17a';
      ctx.beginPath();
      ctx.ellipse(-8 * s, -3 * s, 36 * s, 5 * s, 0.03, 0, TAU);
      ctx.fill();

      // tiny tree
      ctx.strokeStyle = '#3b2b22';
      ctx.lineWidth = 2 * s;
      ctx.beginPath();
      ctx.moveTo(12 * s, -4 * s);
      ctx.lineTo(12 * s, -18 * s);
      ctx.stroke();
      ctx.fillStyle = '#4f8b58';
      ctx.beginPath();
      ctx.arc(12 * s, -23 * s, 9 * s, 0, TAU);
      ctx.fill();

      // waterfall
      const wf = ctx.createLinearGradient(0, 0, 0, 80 * s);
      wf.addColorStop(0, 'rgba(166,240,255,0.6)');
      wf.addColorStop(1, 'rgba(120,210,255,0)');
      ctx.fillStyle = wf;
      ctx.fillRect(-2 * s, 4 * s, 3 * s, 50 * s);

      ctx.restore();
    }
  }

  drawBirds(ctx, t) {
    ctx.save();
    ctx.strokeStyle = 'rgba(37,22,48,0.6)';
    ctx.lineWidth = 1.6;
    for (const b of this.birds) {
      const x = ((b.x + t * b.speed) % 1800) - 100;
      const y = b.y + Math.sin(t * 0.6 + b.phase) * 6;
      const flap = Math.sin(t * 4 + b.phase) * 5;
      ctx.beginPath();
      ctx.moveTo(x - 9 * b.s, y + flap * 0.4);
      ctx.quadraticCurveTo(x - 4 * b.s, y - 3 * b.s, x, y);
      ctx.quadraticCurveTo(x + 4 * b.s, y - 3 * b.s, x + 9 * b.s, y + flap * 0.4);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawSea(ctx, t) {
    const sea = ctx.createLinearGradient(0, 655, 0, 900);
    sea.addColorStop(0, 'rgba(43,29,78,0.1)');
    sea.addColorStop(0.24, '#3b2a66');
    sea.addColorStop(0.55, '#273462');
    sea.addColorStop(1, '#12253f');
    ctx.fillStyle = sea;
    ctx.fillRect(0, 655, this.width, 245);

    // horizon glow
    const glow = ctx.createRadialGradient(1150, 690, 4, 1150, 690, 420);
    glow.addColorStop(0, 'rgba(255,185,120,0.32)');
    glow.addColorStop(1, 'rgba(255,140,100,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(700, 640, 900, 240);

    // distant wave lines
    ctx.save();
    ctx.strokeStyle = 'rgba(255,186,150,0.2)';
    ctx.lineWidth = 1.2;
    for (let i = 0; i < 9; i += 1) {
      const y = 680 + i * 18;
      ctx.beginPath();
      for (let x = 0; x <= this.width; x += 20) {
        const yy = y + Math.sin(x * 0.016 + t * 0.8 + i) * (1.2 + i * 0.2);
        if (x === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
      }
      ctx.globalAlpha = 0.5 - i * 0.045;
      ctx.stroke();
    }
    ctx.restore();
  }

  drawWater(ctx, t) {
    const y = WATER_Y;
    ctx.save();
    const grad = ctx.createLinearGradient(0, y - 10, 0, 900);
    grad.addColorStop(0, 'rgba(92,224,255,0.38)');
    grad.addColorStop(0.14, 'rgba(37,154,203,0.62)');
    grad.addColorStop(0.5, 'rgba(18,88,145,0.86)');
    grad.addColorStop(1, 'rgba(8,44,92,0.96)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(0, y + 3);
    for (let x = 0; x <= this.width; x += 14) {
      const yy = y + 3 + Math.sin(x * 0.014 + t * 1.4) * 3 + Math.sin(x * 0.045 + t * 2.2) * 1.4;
      ctx.lineTo(x, yy);
    }
    ctx.lineTo(this.width, 900);
    ctx.lineTo(0, 900);
    ctx.closePath();
    ctx.fill();

    ctx.globalAlpha = 0.9;
    ctx.strokeStyle = 'rgba(175,249,255,0.7)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let x = 0; x <= this.width; x += 12) {
      const yy = y + 3 + Math.sin(x * 0.014 + t * 1.4) * 3 + Math.sin(x * 0.045 + t * 2.2) * 1.4;
      if (x === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
    }
    ctx.stroke();

    for (const s of this.sparkles) {
      const a = 0.24 + Math.abs(Math.sin(t * s.speed + s.phase)) * 0.5;
      ctx.globalAlpha = a * 0.55;
      ctx.fillStyle = '#d9ffff';
      ctx.fillRect(s.x, s.y + Math.sin(t * 1.5 + s.phase) * 2, 2, 1);
    }
    ctx.restore();
  }

  drawStorm(ctx, game, t) {
    // slim storm wall pulse on the far right, a nod to the shrinking circle
    ctx.save();
    const pulse = 0.04 + (Math.sin(t * 0.7) * 0.5 + 0.5) * 0.035;
    const grad = ctx.createLinearGradient(1600, 0, 1440, 0);
    grad.addColorStop(0, `rgba(155,86,255,${pulse + 0.08})`);
    grad.addColorStop(0.4, `rgba(124,66,210,${pulse})`);
    grad.addColorStop(1, 'rgba(100,60,180,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(1380, 0, 220, 900);
    ctx.restore();
  }

  drawBuildings(ctx, game, t) {
    const pieces = game.buildings;
    for (const piece of pieces) {
      this.drawPiece(ctx, piece, game, t);
    }
  }

  drawPiece(ctx, piece, game, t) {
    const m = MATERIALS[piece.material] || MATERIALS.wood;
    const teamColor = piece.team === 0 ? '88,238,255' : '255,109,114';
    const age = clamp(piece.age, 0, 1);
    const pop = age < 1 ? 1 + Math.sin(age * Math.PI) * 0.045 : 1;
    const hpRatio = clamp(piece.hp / piece.maxHp, 0, 1);
    const alpha = piece.fading ? clamp(piece.life, 0, 1) : 1;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(piece.x + piece.w / 2, piece.y + piece.h / 2);
    ctx.scale(pop, pop);
    ctx.translate(-piece.w / 2, -piece.h / 2);

    if (piece.type === 'wall') {
      this.drawPanel(ctx, 0, 0, piece.w, piece.h, m, 'wall', hpRatio);
    } else if (piece.type === 'floor') {
      this.drawPanel(ctx, 0, 0, piece.w, piece.h, m, 'floor', hpRatio);
    } else if (piece.type === 'ramp') {
      this.drawRamp(ctx, piece, m, hpRatio);
    }

    ctx.restore();

    // team glow
    ctx.save();
    ctx.globalAlpha = alpha * (piece.blueprint ? 0.9 : 0.55);
    ctx.shadowColor = `rgba(${teamColor},0.8)`;
    ctx.shadowBlur = 10;
    ctx.strokeStyle = `rgba(${teamColor},${piece.blueprint ? 0.9 : 0.38})`;
    ctx.lineWidth = 1.4;
    if (piece.type === 'ramp') {
      ctx.beginPath();
      ctx.moveTo(piece.x, piece.y + piece.h);
      ctx.lineTo(piece.x + (piece.flip ? 0 : piece.w), piece.y + (piece.flip ? piece.h : 0));
      ctx.lineTo(piece.x + (piece.flip ? 0 : piece.w), piece.y + piece.h);
      ctx.closePath();
      ctx.stroke();
    } else {
      roundRectPath(ctx, piece.x, piece.y, piece.w, piece.h, 2);
      ctx.stroke();
    }
    ctx.restore();

    // damage bar only after real damage
    if (hpRatio < 0.98 && !piece.blueprint) {
      ctx.save();
      ctx.globalAlpha = alpha;
      const w = Math.min(piece.w + 8, 54);
      const x = piece.x + piece.w / 2 - w / 2;
      const y = piece.y - 7;
      ctx.fillStyle = 'rgba(8,5,16,0.7)';
      roundRectPath(ctx, x, y, w, 4, 2);
      ctx.fill();
      ctx.fillStyle = hpRatio > 0.5 ? `rgba(${teamColor},0.9)` : '#ff9c4a';
      roundRectPath(ctx, x, y, Math.max(2, w * hpRatio), 4, 2);
      ctx.fill();
      ctx.restore();
    }
  }

  drawPanel(ctx, x, y, w, h, m, kind, hpRatio) {
    const grad = ctx.createLinearGradient(x, y, x + w, y + h);
    grad.addColorStop(0, m.light);
    grad.addColorStop(0.2, m.base);
    grad.addColorStop(1, m.dark);
    ctx.fillStyle = grad;
    roundRectPath(ctx, x, y, w, h, 2.5);
    ctx.fill();
    ctx.strokeStyle = m.edge;
    ctx.lineWidth = 1.6;
    ctx.stroke();

    ctx.save();
    roundRectPath(ctx, x + 1, y + 1, w - 2, h - 2, 2);
    ctx.clip();

    if (kind === 'wall') {
      if (m === MATERIALS.wood) {
        for (let i = 1; i < 6; i += 1) {
          const yy = y + (h / 6) * i;
          ctx.strokeStyle = 'rgba(74,42,20,0.45)';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(x, yy);
          ctx.lineTo(x + w, yy + Math.sin(i) * 1.5);
          ctx.stroke();
        }
        ctx.fillStyle = 'rgba(255,233,180,0.2)';
        ctx.fillRect(x + 2, y + 2, 2, h - 4);
      } else if (m === MATERIALS.brick) {
        for (let row = 0; row < 6; row += 1) {
          const yy = y + row * (h / 6);
          ctx.strokeStyle = 'rgba(72,25,25,0.55)';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(x, yy);
          ctx.lineTo(x + w, yy);
          ctx.stroke();
          const offset = row % 2 ? 0 : w / 2;
          ctx.beginPath();
          ctx.moveTo(x + offset, yy);
          ctx.lineTo(x + offset, yy + h / 6);
          ctx.stroke();
        }
        ctx.fillStyle = 'rgba(255,188,165,0.16)';
        ctx.fillRect(x + 2, y + 2, 2, h - 4);
      } else {
        for (let i = 0; i < 4; i += 1) {
          const yy = y + 4 + i * (h - 8) / 4;
          ctx.strokeStyle = 'rgba(30,48,68,0.5)';
          ctx.lineWidth = 1.4;
          ctx.beginPath();
          ctx.moveTo(x + 2, yy);
          ctx.lineTo(x + w - 2, yy);
          ctx.stroke();
        }
        ctx.fillStyle = 'rgba(255,255,255,0.38)';
        for (let i = 0; i < 6; i += 1) {
          ctx.beginPath();
          ctx.arc(x + 4, y + 7 + i * (h - 12) / 5, 0.9, 0, TAU);
          ctx.fill();
          ctx.beginPath();
          ctx.arc(x + w - 4, y + 7 + i * (h - 12) / 5, 0.9, 0, TAU);
          ctx.fill();
        }
      }
    } else if (kind === 'floor') {
      if (m === MATERIALS.wood) {
        for (let i = 1; i < 5; i += 1) {
          const xx = x + (w / 5) * i;
          ctx.strokeStyle = 'rgba(75,44,21,0.4)';
          ctx.beginPath();
          ctx.moveTo(xx, y);
          ctx.lineTo(xx, y + h);
          ctx.stroke();
        }
      } else if (m === MATERIALS.brick) {
        for (let i = 0; i < 4; i += 1) {
          ctx.strokeStyle = 'rgba(70,25,26,0.45)';
          ctx.beginPath();
          ctx.moveTo(x + (w / 4) * i, y);
          ctx.lineTo(x + (w / 4) * i, y + h);
          ctx.stroke();
        }
      } else {
        ctx.strokeStyle = 'rgba(34,51,74,0.45)';
        for (let i = 0; i < 5; i += 1) {
          ctx.beginPath();
          ctx.moveTo(x + 5 + i * (w - 10) / 4, y + 2);
          ctx.lineTo(x + 5 + i * (w - 10) / 4, y + h - 2);
          ctx.stroke();
        }
      }
      ctx.fillStyle = 'rgba(255,255,255,0.16)';
      ctx.fillRect(x + 2, y + 2, w - 4, 1.5);
      ctx.fillStyle = 'rgba(0,0,0,0.22)';
      ctx.fillRect(x + 2, y + h - 3, w - 4, 2);
    }

    if (hpRatio < 0.6) {
      ctx.strokeStyle = 'rgba(18,9,18,0.5)';
      ctx.lineWidth = 1.2;
      for (let i = 0; i < 3; i += 1) {
        ctx.beginPath();
        const cx = x + w * (0.2 + i * 0.28);
        ctx.moveTo(cx, y + 3);
        ctx.lineTo(cx + 5 - i * 3, y + h * 0.28);
        ctx.lineTo(cx - 2, y + h * 0.52);
        if (hpRatio < 0.3) {
          ctx.lineTo(cx + 6, y + h * 0.75);
          ctx.lineTo(cx - 1, y + h - 3);
        }
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  drawRamp(ctx, piece, m, hpRatio) {
    const { x, y, w, h, flip } = piece;
    const grad = ctx.createLinearGradient(x, flip ? y : y + h, x + w, flip ? y + h : y);
    grad.addColorStop(0, m.light);
    grad.addColorStop(0.18, m.base);
    grad.addColorStop(1, m.dark);
    ctx.fillStyle = grad;
    ctx.beginPath();
    if (flip) {
      ctx.moveTo(x, y);
      ctx.lineTo(x + w, y + h);
      ctx.lineTo(x, y + h);
    } else {
      ctx.moveTo(x, y + h);
      ctx.lineTo(x + w, y);
      ctx.lineTo(x + w, y + h);
    }
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = m.edge;
    ctx.lineWidth = 1.6;
    ctx.stroke();

    ctx.save();
    ctx.clip();
    ctx.strokeStyle = m === MATERIALS.metal ? 'rgba(31,48,70,0.5)' : 'rgba(72,40,20,0.45)';
    ctx.lineWidth = 1.3;
    for (let i = 1; i < 5; i += 1) {
      const xx = x + (w / 5) * i;
      ctx.beginPath();
      if (flip) {
        ctx.moveTo(xx, y);
        ctx.lineTo(xx, y + h);
      } else {
        ctx.moveTo(xx, y + h);
        ctx.lineTo(xx, y + h - (h / w) * (xx - x));
      }
      ctx.stroke();
    }
    // ladder-like cross brace
    ctx.strokeStyle = m === MATERIALS.metal ? 'rgba(230,246,255,0.33)' : 'rgba(255,226,166,0.25)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    if (flip) {
      ctx.moveTo(x + 2, y + h * 0.5);
      ctx.lineTo(x + w * 0.5, y + 2);
    } else {
      ctx.moveTo(x + 2, y + h - 2);
      ctx.lineTo(x + w * 0.5, y + h - h * 0.5);
    }
    ctx.stroke();
    ctx.restore();
  }

  drawWormShadows(ctx, game) {
    ctx.save();
    for (const worm of game.worms) {
      if (worm.dead) continue;
      ctx.fillStyle = 'rgba(10,5,18,0.25)';
      ctx.beginPath();
      ctx.ellipse(worm.x, worm.y + 2, 16, 5, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawWorms(ctx, game, t) {
    for (const worm of game.worms) {
      if (worm.dead) {
        if (worm.grave) this.drawGrave(ctx, worm);
        continue;
      }
      const active = game.currentWorm === worm && !game.isOver;
      this.drawWorm(ctx, worm, game, active, t);
    }
  }

  drawGrave(ctx, worm) {
    const x = worm.grave.x;
    const y = worm.grave.y;
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = 'rgba(14,9,24,0.25)';
    ctx.beginPath();
    ctx.ellipse(0, 2, 11, 3, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#665b76';
    roundRectPath(ctx, -5, -15, 10, 16, 4);
    ctx.fill();
    ctx.strokeStyle = '#342c44';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    ctx.fillStyle = '#2e253e';
    ctx.font = `900 6px ${FONT}`;
    ctx.textAlign = 'center';
    ctx.fillText('RIP', 0, -5);
    ctx.strokeStyle = '#5b4f6e';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-7, -19);
    ctx.lineTo(7, -19);
    ctx.stroke();
    ctx.restore();
  }

  drawWorm(ctx, worm, game, active, t) {
    const team = worm.team;
    const bodyDark = team === 0 ? '#268a6a' : '#9a3546';
    const body = team === 0 ? '#6ce9ac' : '#ff8790';
    const bodyLight = team === 0 ? '#c5ffe0' : '#ffd0ce';
    const outline = team === 0 ? '#113d38' : '#4b1626';
    const aim = worm.aimAngle ?? -0.5;
    const facing = Math.cos(aim) >= 0 ? 1 : -1;
    const moving = Math.abs(worm.vx) > 8 && worm.onGround;
    const wiggle = Math.sin(t * (moving ? 12 : 2.2) + worm.phase) * (moving ? 2.4 : 0.9);
    const jumpSquash = worm.onGround ? 0 : clamp(-worm.vy / 500, -0.12, 0.12);
    const bob = Math.sin(t * 2.3 + worm.phase) * 1.2;
    const hurt = worm.hurtTimer > 0;

    ctx.save();
    ctx.translate(worm.x, worm.y - 1);
    ctx.scale(1 + jumpSquash, 1 - jumpSquash);
    ctx.translate(0, bob);

    // Active ring / glow
    if (active) {
      ctx.save();
      const pulse = 0.5 + Math.sin(t * 3.4) * 0.18;
      ctx.strokeStyle = `rgba(255,225,74,${pulse})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.ellipse(0, 1, 22, 7, 0, 0, TAU);
      ctx.stroke();
      const grad = ctx.createRadialGradient(0, -26, 2, 0, -26, 44);
      grad.addColorStop(0, 'rgba(255,225,74,0.12)');
      grad.addColorStop(1, 'rgba(255,225,74,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, -26, 44, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // Tail and body segments (back to front)
    const segments = 6;
    for (let i = 0; i < segments; i += 1) {
      const p = i / (segments - 1);
      const sway = Math.sin(t * (moving ? 10 : 2) + worm.phase + p * 3.4) * (2.6 + p * 1.5);
      const x = sway + facing * (1 - p) * 2;
      const y = -7 - p * 33;
      const r = 6.6 + p * 3.4;
      ctx.beginPath();
      ctx.ellipse(x, y, r * 0.94, r, 0, 0, TAU);
      ctx.fillStyle = bodyDark;
      ctx.fill();
      ctx.strokeStyle = outline;
      ctx.lineWidth = 1.4;
      ctx.stroke();

      // belly stripe
      ctx.beginPath();
      ctx.ellipse(x - facing * r * 0.18, y + r * 0.15, r * 0.52, r * 0.62, 0.12, 0, TAU);
      ctx.fillStyle = body;
      ctx.fill();

      // band + highlight
      ctx.beginPath();
      ctx.arc(x, y, r * 0.9, -2.45, -1.05);
      ctx.strokeStyle = withAlpha(bodyLight, 0.55);
      ctx.lineWidth = 1.6;
      ctx.stroke();
      if (i % 2 === 0) {
        ctx.beginPath();
        ctx.arc(x, y, r * 0.92, 0.5, 1.7);
        ctx.strokeStyle = withAlpha(outline, 0.35);
        ctx.lineWidth = 1.4;
        ctx.stroke();
      }
    }

    const headX = Math.sin(t * (moving ? 10 : 2) + worm.phase + 3.4) * 2.2 + facing * 1.5;
    const headY = -43;
    const headR = 9.8;

    // helm / bandana
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(headX, headY - 2, headR + 1.5, headR * 0.86, -0.15, Math.PI, TAU);
    ctx.fillStyle = team === 0 ? '#2b9ca5' : '#a63d52';
    ctx.fill();
    ctx.strokeStyle = outline;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // bandana tails
    ctx.beginPath();
    ctx.moveTo(headX - facing * 8, headY - 5);
    ctx.quadraticCurveTo(headX - facing * 17, headY - 3 + Math.sin(t * 5) * 1.4, headX - facing * 18, headY + 3);
    ctx.quadraticCurveTo(headX - facing * 11, headY + 2, headX - facing * 8, headY + 1);
    ctx.fillStyle = team === 0 ? '#2b9ca5' : '#a63d52';
    ctx.fill();
    ctx.restore();

    // Head
    ctx.beginPath();
    ctx.arc(headX, headY, headR, 0, TAU);
    const faceGrad = ctx.createRadialGradient(headX - 3, headY - 4, 1, headX, headY, headR);
    faceGrad.addColorStop(0, bodyLight);
    faceGrad.addColorStop(0.5, body);
    faceGrad.addColorStop(1, bodyDark);
    ctx.fillStyle = hurt ? '#fff2d6' : faceGrad;
    ctx.fill();
    ctx.strokeStyle = outline;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Eyes look toward aim
    const lookX = Math.cos(aim) * 1.55;
    const lookY = Math.sin(aim) * 1.2;
    for (const side of [-1, 1]) {
      const ex = headX + side * 3.9;
      const ey = headY - 1.6;
      ctx.beginPath();
      ctx.arc(ex, ey, 2.7, 0, TAU);
      ctx.fillStyle = '#fffdf6';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(ex + lookX, ey + lookY, 1.35, 0, TAU);
      ctx.fillStyle = '#171020';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(ex + lookX - 0.4, ey + lookY - 0.5, 0.42, 0, TAU);
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.fill();
    }

    // Mouth
    ctx.beginPath();
    if (hurt) {
      ctx.ellipse(headX, headY + 4.2, 1.6, 1.9, 0, 0, TAU);
      ctx.fillStyle = '#4a1420';
      ctx.fill();
    } else {
      ctx.arc(headX + 0.2, headY + 3.2, 2.1, 0.15, Math.PI - 0.15);
      ctx.strokeStyle = outline;
      ctx.lineWidth = 1.1;
      ctx.stroke();
    }

    // cheek blush
    ctx.globalAlpha = 0.28;
    ctx.fillStyle = team === 0 ? '#ff9cc5' : '#ffb1a9';
    ctx.beginPath();
    ctx.arc(headX + 5.4, headY + 2.5, 1.8, 0, TAU);
    ctx.arc(headX - 6.4, headY + 2.5, 1.3, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 1;

    // Weapon + arm
    this.drawWeapon(ctx, worm, game, headX, headY, aim, t);

    if (hurt) {
      ctx.globalCompositeOperation = 'source-atop';
      ctx.fillStyle = `rgba(255,80,80,${0.3 + Math.sin(t * 50) * 0.12})`;
      ctx.beginPath();
      ctx.arc(headX, headY - 20, 34, 0, TAU);
      ctx.fill();
    }

    ctx.restore();

    // Nameplate
    if (active || worm.showPlate > 0) {
      this.drawPlate(ctx, worm, active, t);
    }
  }

  drawWeapon(ctx, worm, game, headX, headY, aim, t) {
    const teamAmmo = game.ammo[worm.team];
    const weapon = worm.weapon || 'bazooka';
    const facing = Math.cos(aim) >= 0 ? 1 : -1;
    ctx.save();
    ctx.translate(headX + facing * 2, headY + 1);
    ctx.rotate(aim);
    if (facing < 0) ctx.scale(1, -1);

    // arm
    ctx.strokeStyle = worm.team === 0 ? '#269a72' : '#a63d52';
    ctx.lineWidth = 3.2;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(0, 2);
    ctx.quadraticCurveTo(8, 6, 13, 2);
    ctx.stroke();

    if (weapon === 'bazooka') {
      ctx.fillStyle = '#2f3349';
      roundRectPath(ctx, 5, -6, 28, 8, 2);
      ctx.fill();
      ctx.strokeStyle = '#111420';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = '#ffcf4a';
      ctx.fillRect(10, -5.2, 5, 6.4);
      ctx.fillStyle = '#6e7795';
      ctx.fillRect(29, -7.5, 5, 11);
      ctx.fillStyle = '#171a27';
      ctx.beginPath();
      ctx.arc(33.5, -2, 2.4, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#b6c8e8';
      ctx.fillRect(13, -8, 2, 3);
    } else if (weapon === 'grenade') {
      ctx.fillStyle = worm.team === 0 ? '#269a72' : '#a63d52';
      ctx.beginPath();
      ctx.arc(14, 0, 3.6, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#6dbb70';
      ctx.beginPath();
      ctx.arc(18, -2, 5.2, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = '#345f39';
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.fillStyle = '#cbd3d7';
      ctx.fillRect(16.5, -9, 3, 3);
    } else if (weapon === 'cluster') {
      ctx.fillStyle = worm.team === 0 ? '#269a72' : '#a63d52';
      ctx.beginPath();
      ctx.arc(13, 0, 3.4, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#bca1fa';
      ctx.beginPath();
      ctx.arc(19, -2, 4.6, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = '#5c3a9e';
      ctx.lineWidth = 1.1;
      ctx.stroke();
      ctx.fillStyle = '#7250b5';
      ctx.beginPath();
      ctx.arc(24.5, 1, 2.1, 0, TAU);
      ctx.fill();
    } else {
      // pickaxe
      ctx.strokeStyle = '#8d5a32';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(4, 3);
      ctx.lineTo(21, -7);
      ctx.stroke();
      ctx.fillStyle = '#cfdcef';
      ctx.beginPath();
      ctx.moveTo(18, -12);
      ctx.quadraticCurveTo(27, -13, 29, -4);
      ctx.quadraticCurveTo(23, -8, 16, -8);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#667a97';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    ctx.restore();
  }

  drawPlate(ctx, worm, active, t) {
    const name = worm.name.toUpperCase();
    const w = 78;
    const h = 19;
    const x = worm.x - w / 2;
    const y = worm.y - 76 - (active ? Math.sin(t * 3) * 2 : 0);
    ctx.save();
    ctx.globalAlpha = active ? 1 : 0.7;
    ctx.fillStyle = 'rgba(11,7,20,0.82)';
    ctx.strokeStyle = active ? 'rgba(255,225,74,0.65)' : 'rgba(255,255,255,0.16)';
    ctx.lineWidth = 1;
    roundRectPath(ctx, x, y, w, h, 6);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = worm.team === 0 ? '#7cf7d4' : '#ff9c9f';
    ctx.font = `900 8px ${FONT}`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(name, x + 6, y + 7);

    const hp = clamp(worm.health / worm.maxHealth, 0, 1);
    ctx.fillStyle = 'rgba(255,255,255,0.13)';
    roundRectPath(ctx, x + 6, y + 12, w - 12, 3, 2);
    ctx.fill();
    ctx.fillStyle = hp > 0.55 ? (worm.team === 0 ? '#6df08a' : '#ff7b7e') : hp > 0.28 ? '#ffca55' : '#ff4d5e';
    roundRectPath(ctx, x + 6, y + 12, (w - 12) * hp, 3, 2);
    ctx.fill();

    if (active) {
      const bounce = Math.sin(t * 3.2) * 3;
      ctx.fillStyle = 'rgba(255,225,74,0.95)';
      ctx.beginPath();
      ctx.moveTo(worm.x - 5, y - 8 + bounce);
      ctx.lineTo(worm.x + 5, y - 8 + bounce);
      ctx.lineTo(worm.x, y - 1 + bounce);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  drawProjectiles(ctx, game, t) {
    for (const p of game.projectiles) {
      ctx.save();
      ctx.translate(p.x, p.y);
      if (p.kind === 'rocket') {
        const angle = Math.atan2(p.vy, p.vx);
        ctx.rotate(angle);
        // exhaust
        const flame = 8 + Math.random() * 8;
        const grad = ctx.createLinearGradient(-14, 0, -14 - flame, 0);
        grad.addColorStop(0, 'rgba(255,247,183,0.95)');
        grad.addColorStop(0.4, 'rgba(255,160,60,0.8)');
        grad.addColorStop(1, 'rgba(255,80,30,0)');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(-12, -4);
        ctx.lineTo(-12 - flame, 0);
        ctx.lineTo(-12, 4);
        ctx.closePath();
        ctx.fill();
        // body
        ctx.fillStyle = '#f4e8cc';
        roundRectPath(ctx, -12, -4.5, 24, 9, 4);
        ctx.fill();
        ctx.strokeStyle = '#2b2438';
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.fillStyle = '#ff6d72';
        ctx.beginPath();
        ctx.moveTo(11, -4.2);
        ctx.lineTo(18, 0);
        ctx.lineTo(11, 4.2);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = '#4c425f';
        ctx.beginPath();
        ctx.moveTo(-11, -4);
        ctx.lineTo(-17, -9);
        ctx.lineTo(-7, -4);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(-11, 4);
        ctx.lineTo(-17, 9);
        ctx.lineTo(-7, 4);
        ctx.closePath();
        ctx.fill();
        ctx.fillStyle = '#65f2ff';
        ctx.beginPath();
        ctx.arc(2, 0, 2.2, 0, TAU);
        ctx.fill();
      } else {
        const r = p.kind === 'cluster' ? 5.2 : 7.2;
        ctx.rotate(p.spin || 0);
        const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, r);
        grad.addColorStop(0, p.kind === 'cluster' ? '#e5d7ff' : '#a7ef9e');
        grad.addColorStop(0.55, p.kind === 'cluster' ? '#a681f0' : '#6bbd70');
        grad.addColorStop(1, p.kind === 'cluster' ? '#5a339e' : '#326a3c');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = '#20301f';
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.strokeStyle = 'rgba(30,40,30,0.45)';
        ctx.beginPath();
        ctx.moveTo(-r, 0);
        ctx.lineTo(r, 0);
        ctx.moveTo(0, -r);
        ctx.lineTo(0, r);
        ctx.stroke();
        ctx.fillStyle = '#d5dde0';
        ctx.fillRect(-1.6, -r - 3, 3.2, 3);
        // blinking fuse
        const spark = Math.abs(Math.sin(t * 18 + (p.spin || 0)));
        ctx.fillStyle = `rgba(255,190,80,${0.55 + spark * 0.45})`;
        ctx.beginPath();
        ctx.arc(0, -r - 4.5, 1.8 + spark * 1.2, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  drawAim(ctx, game, t) {
    if (game.phase !== 'player' || game.isOver) return;
    const preview = game.getAimPreview();
    if (!preview) return;
    const worm = game.currentWorm;
    if (!worm) return;

    if (game.buildMode) {
      this.drawBuildOverlay(ctx, game, t);
      return;
    }

    const { points, impact, muzzle } = preview;
    if (points.length > 1) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 1; i < points.length; i += 2) {
        const p = points[i];
        const a = clamp(1 - i / points.length, 0.08, 1);
        ctx.fillStyle = `rgba(255,225,122,${0.14 + a * 0.5})`;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 1.6 + a * 1.7, 0, TAU);
        ctx.fill();
      }
      ctx.restore();

      if (impact) {
        ctx.save();
        const pulse = 0.6 + Math.sin(t * 7) * 0.25;
        ctx.strokeStyle = `rgba(255,225,74,${pulse})`;
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.ellipse(impact.x, impact.y, 9 + pulse * 3, 4 + pulse * 1.2, 0, 0, TAU);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(impact.x, impact.y, 2, 0, TAU);
        ctx.fillStyle = 'rgba(255,225,74,0.8)';
        ctx.fill();
        ctx.restore();
      }
    }

    // power gauge around the worm
    const power = game.chargePower;
    const pivotX = worm.x;
    const pivotY = worm.y - 41;
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(12,7,22,0.55)';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.arc(pivotX, pivotY, 34, -2.5, 2.5);
    ctx.stroke();
    if (power > 0) {
      const grad = ctx.createLinearGradient(pivotX - 30, pivotY, pivotX + 30, pivotY);
      grad.addColorStop(0, '#7cffbb');
      grad.addColorStop(0.5, '#ffe14a');
      grad.addColorStop(1, '#ff6d72');
      ctx.strokeStyle = grad;
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(pivotX, pivotY, 34, -2.5, -2.5 + 5 * clamp(power, 0, 1));
      ctx.stroke();
    }
    ctx.restore();

    // angle tick line
    ctx.save();
    ctx.strokeStyle = 'rgba(255,225,74,0.5)';
    ctx.lineWidth = 1.4;
    ctx.setLineDash([3, 4]);
    ctx.beginPath();
    ctx.moveTo(pivotX, pivotY);
    ctx.lineTo(pivotX + Math.cos(worm.aimAngle) * 38, pivotY + Math.sin(worm.aimAngle) * 38);
    ctx.stroke();
    ctx.restore();

    if (game.mouse.active) {
      this.drawReticle(ctx, game.mouse.x, game.mouse.y, game.chargePower > 0, t);
    }
  }

  drawReticle(ctx, x, y, charging, t) {
    ctx.save();
    const spin = t * (charging ? 2.8 : 0.7);
    ctx.translate(x, y);
    ctx.rotate(spin);
    ctx.strokeStyle = charging ? 'rgba(255,225,74,0.95)' : 'rgba(255,255,255,0.7)';
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 4; i += 1) {
      ctx.beginPath();
      ctx.arc(0, 0, 10, i * (TAU / 4) + 0.14, i * (TAU / 4) + 0.62);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.arc(0, 0, 2, 0, TAU);
    ctx.fillStyle = charging ? '#ffe14a' : 'rgba(255,255,255,0.8)';
    ctx.fill();
    ctx.restore();
  }

  drawBuildOverlay(ctx, game, t) {
    const worm = game.currentWorm;
    if (!worm) return;
    const ghost = game.getBuildGhost();
    if (!ghost) return;
    const grid = game.buildGrid;

    ctx.save();
    // range circle
    ctx.globalAlpha = 0.22;
    ctx.strokeStyle = 'rgba(88,238,255,0.8)';
    ctx.setLineDash([5, 9]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(worm.x, worm.y - 20, game.buildRange, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;

    // local snapping grid
    const cx = Math.round(ghost.piece.x / grid) * grid;
    const cy = Math.round(ghost.piece.y / grid) * grid;
    ctx.globalAlpha = 0.32;
    ctx.strokeStyle = 'rgba(88,238,255,0.55)';
    ctx.lineWidth = 1;
    for (let i = -3; i <= 3; i += 1) {
      const gx = cx + i * grid;
      const gy = cy + i * grid;
      ctx.beginPath();
      ctx.moveTo(gx, cy - grid * 3);
      ctx.lineTo(gx, cy + grid * 3);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(cx - grid * 3, gy);
      ctx.lineTo(cx + grid * 3, gy);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    this.drawGhostPiece(ctx, ghost, t);
    ctx.restore();
  }

  drawGhostPiece(ctx, ghost, t) {
    const piece = ghost.piece;
    const valid = ghost.valid;
    const color = valid ? '88,238,255' : '255,90,100';
    ctx.save();
    ctx.globalAlpha = 0.9;
    ctx.strokeStyle = `rgba(${color},0.95)`;
    ctx.fillStyle = `rgba(${color},0.19)`;
    ctx.lineWidth = 1.8;
    ctx.setLineDash([5, 4]);
    ctx.lineDashOffset = -t * 18;

    if (piece.type === 'ramp') {
      ctx.beginPath();
      if (piece.flip) {
        ctx.moveTo(piece.x, piece.y);
        ctx.lineTo(piece.x + piece.w, piece.y + piece.h);
        ctx.lineTo(piece.x, piece.y + piece.h);
      } else {
        ctx.moveTo(piece.x, piece.y + piece.h);
        ctx.lineTo(piece.x + piece.w, piece.y);
        ctx.lineTo(piece.x + piece.w, piece.y + piece.h);
      }
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    } else {
      roundRectPath(ctx, piece.x, piece.y, piece.w, piece.h, 3);
      ctx.fill();
      ctx.stroke();
    }

    // corner ticks
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;
    const corners = [
      [piece.x, piece.y],
      [piece.x + piece.w, piece.y],
      [piece.x, piece.y + piece.h],
      [piece.x + piece.w, piece.y + piece.h],
    ];
    ctx.strokeStyle = `rgba(${color},1)`;
    ctx.lineWidth = 2.4;
    for (const [x, y] of corners) {
      ctx.beginPath();
      ctx.moveTo(x - 4, y);
      ctx.lineTo(x + 4, y);
      ctx.moveTo(x, y - 4);
      ctx.lineTo(x, y + 4);
      ctx.stroke();
    }

    if (!valid) {
      ctx.fillStyle = 'rgba(255,90,100,0.95)';
      ctx.font = `900 9px ${FONT}`;
      ctx.textAlign = 'center';
      ctx.fillText(ghost.reason.toUpperCase(), piece.x + piece.w / 2, piece.y - 12);
    } else {
      ctx.fillStyle = 'rgba(255,225,74,0.95)';
      ctx.font = `900 9px ${FONT}`;
      ctx.textAlign = 'center';
      ctx.fillText(`${game.buildCost()} MATS`, piece.x + piece.w / 2, piece.y - 12);
    }
    ctx.restore();
  }

  drawAtmosphere(ctx, t) {
    // fireflies / dust
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const e of this.embers) {
      const x = (e.x + Math.sin(t * 0.3 + e.phase) * 25 + t * e.speed * 4) % 1650;
      const y = e.y + Math.cos(t * 0.45 + e.phase) * 14;
      const a = 0.12 + (Math.sin(t * e.speed + e.phase) * 0.5 + 0.5) * 0.45;
      ctx.fillStyle = `rgba(255,231,157,${a * 0.55})`;
      ctx.beginPath();
      ctx.arc(x, y, e.s, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // Edge shade
    const vignette = ctx.createRadialGradient(800, 470, 310, 800, 470, 950);
    vignette.addColorStop(0, 'rgba(0,0,0,0)');
    vignette.addColorStop(0.72, 'rgba(7,4,16,0.16)');
    vignette.addColorStop(1, 'rgba(5,3,12,0.62)');
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, this.width, this.height);
  }

  drawOverlayEffects(ctx, game, t) {
    if (game.flash > 0) {
      ctx.save();
      ctx.globalAlpha = clamp(game.flash, 0, 0.55);
      ctx.fillStyle = '#fff3cf';
      ctx.fillRect(0, 0, this.viewWidth, this.viewHeight);
      ctx.restore();
    }
    if (game.hitVignette > 0) {
      const grad = ctx.createRadialGradient(this.viewWidth / 2, this.viewHeight / 2, this.viewHeight * 0.25, this.viewWidth / 2, this.viewHeight / 2, this.viewHeight * 0.8);
      grad.addColorStop(0, 'rgba(255,40,70,0)');
      grad.addColorStop(1, `rgba(255,30,60,${game.hitVignette * 0.3})`);
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, this.viewWidth, this.viewHeight);
    }
  }

  drawLetterbox(ctx, t) {
    const { offsetX, offsetY, viewWidth, viewHeight } = this;
    if (offsetX > 2) {
      const gradL = ctx.createLinearGradient(0, 0, offsetX, 0);
      gradL.addColorStop(0, '#090614');
      gradL.addColorStop(1, '#120c22');
      ctx.fillStyle = gradL;
      ctx.fillRect(0, 0, offsetX, viewHeight);
      const gradR = ctx.createLinearGradient(viewWidth - offsetX, 0, viewWidth, 0);
      gradR.addColorStop(0, '#120c22');
      gradR.addColorStop(1, '#090614');
      ctx.fillStyle = gradR;
      ctx.fillRect(viewWidth - offsetX, 0, offsetX, viewHeight);
    }
    if (offsetY > 2) {
      ctx.fillStyle = '#090614';
      ctx.fillRect(0, 0, viewWidth, offsetY);
      ctx.fillRect(0, viewHeight - offsetY, viewWidth, offsetY);
    }

    // fine screen wash and scanline
    ctx.save();
    ctx.globalAlpha = 0.07;
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    for (let y = 0; y < viewHeight; y += 4) {
      ctx.fillRect(0, y, viewWidth, 1);
    }
    ctx.restore();

    ctx.save();
    const edge = ctx.createLinearGradient(0, 0, 0, 90);
    edge.addColorStop(0, 'rgba(0,0,0,0.3)');
    edge.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = edge;
    ctx.fillRect(0, 0, viewWidth, 90);
    ctx.restore();
  }
}

import { Terrain } from './terrain.js';
import { Particles } from './particles.js';
import {
  angleTo,
  approach,
  clamp,
  explosionDamage,
  makeTrajectoryPreview,
  mulberry32,
  pick,
  pointInTriangle,
  range,
  snap,
  windToAccel,
} from './logic.js';

export const WORLD = { width: 1600, height: 900, waterY: 868 };
export const BUILD_GRID = 40;
export const BUILD_RANGE = 430;
export const TURN_TIME = 60;

const GRAVITY = 900;
const WATER = WORLD.waterY;
const WORM_SPEED = 122;
const JUMP_SPEED = 362;

const COST = { wall: 20, floor: 15, ramp: 25 };
const SIZE = {
  wall: { w: 16, h: 84 },
  floor: { w: 88, h: 16 },
  ramp: { w: 88, h: 88 },
};
const MATERIAL_HP = { wood: 95, brick: 175, metal: 285 };

const WEAPONS = {
  bazooka: { speed: 1010, gravity: 730, blast: 86, damage: 56, radius: 7, name: 'BAZOOKA' },
  grenade: { speed: 840, gravity: 840, blast: 98, damage: 68, radius: 8, fuse: 2.15, name: 'GRENADE' },
  cluster: { speed: 890, gravity: 760, blast: 72, damage: 42, radius: 7, name: 'CLUSTER' },
  pickaxe: { name: 'PICKAXE' },
};

const NAMES = {
  0: ['PIP', 'NIBBLES', 'BOLT'],
  1: ['REX', 'VEX', 'NYX'],
};

const AI_LINES = [
  'STORM SQUAD IS LINING UP A SHOT',
  'ENEMY WORM HAS A CLEAR ARC',
  'INCOMING ARTILLERY',
  'THE STORM SQUAD IS BUILDING UP',
];

function pieceRect(piece) {
  return { x: piece.x, y: piece.y, w: piece.w, h: piece.h };
}

function rectCircle(x, y, w, h, cx, cy, r) {
  const nx = clamp(cx, x, x + w);
  const ny = clamp(cy, y, y + h);
  const dx = cx - nx;
  const dy = cy - ny;
  return dx * dx + dy * dy <= r * r;
}

function rectDistance(x, y, w, h, cx, cy) {
  const nx = clamp(cx, x, x + w);
  const ny = clamp(cy, y, y + h);
  return Math.hypot(cx - nx, cy - ny);
}

export class Game {
  constructor({ audio, onEvent } = {}) {
    this.audio = audio;
    this.onEvent = onEvent || (() => {});
    this.particles = new Particles();
    this.terrain = new Terrain(WORLD.width, WORLD.height);
    this.keys = { left: false, right: false, jump: false };
    this.mouse = { x: 800, y: 420, active: false, down: false };
    this.worms = [];
    this.buildings = [];
    this.projectiles = [];
    this.floaters = [];
    this.shake = 0;
    this.flash = 0;
    this.hitVignette = 0;
    this.time = 0;
    this.phase = 'menu';
    this.isOver = false;
    this.buildGrid = BUILD_GRID;
    this.buildRange = BUILD_RANGE;
    this.chargePower = 0;
    this.charging = false;
    this.buildMode = false;
    this.selectedBuild = 'wall';
    this.selectedWeapon = ['bazooka', 'bazooka'];
    this.currentWeapon = 'bazooka';
    this.material = 'wood';
    this.buildsLeft = 4;
    this.timer = TURN_TIME;
    this.wind = 0;
    this.turn = 1;
    this.currentTeam = 0;
    this.currentWorm = null;
    this.wormCursor = [0, 0];
    this.aiState = 'idle';
    this.aiTimer = 0;
    this.aiTarget = null;
    this.shotActive = false;
    this.endDelay = 0;
    this.harvestCooldown = 0;
    this.turnEnding = false;
    this.rng = mulberry32(1);
    this.seed = 1;
    this.stats = { shots: [0, 0], damage: [0, 0], builds: [0, 0], turns: 0 };
    this.newMatch(Date.now() & 0x7fffffff, true);
  }

  setAudio(audio) {
    this.audio = audio;
  }

  newMatch(seed = Date.now() & 0x7fffffff, menu = false) {
    this.seed = seed >>> 0;
    this.rng = mulberry32(this.seed);
    this.terrain.generate(this.rng, this.seed);
    this.particles.clear();
    this.buildings = [];
    this.projectiles = [];
    this.floaters = [];
    this.worms = [];
    this.isOver = false;
    this.phase = menu ? 'menu' : 'player';
    this.turn = 1;
    this.currentTeam = 0;
    this.wormCursor = [0, 0];
    this.wind = 0;
    this.timer = TURN_TIME;
    this.chargePower = 0;
    this.charging = false;
    this.buildMode = false;
    this.selectedBuild = 'wall';
    this.selectedWeapon = ['bazooka', 'bazooka'];
    this.currentWeapon = 'bazooka';
    this.buildsLeft = 4;
    this.material = 'wood';
    this.shotActive = false;
    this.endDelay = 0;
    this.turnEnding = false;
    this.aiState = 'idle';
    this.aiTimer = 0;
    this.shake = 0;
    this.flash = 0;
    this.hitVignette = 0;
    this.stats = { shots: [0, 0], damage: [0, 0], builds: [0, 0], turns: 0 };

    this.materials = [
      { wood: 160, brick: 90, metal: 45 },
      { wood: 160, brick: 90, metal: 45 },
    ];
    this.ammo = [
      { bazooka: Infinity, grenade: 3, cluster: 1 },
      { bazooka: Infinity, grenade: 3, cluster: 1 },
    ];

    const spawns = {
      0: [286, 370, 454],
      1: [1314, 1230, 1146],
    };
    for (const team of [0, 1]) {
      spawns[team].forEach((x, index) => {
        const ground = this.terrain.groundBelow(x, 0, this.terrain.height);
        const y = Math.min(ground ?? 640, WATER - 30) - 1;
        const facing = team === 0 ? 1 : -1;
        this.worms.push({
          team,
          index,
          name: NAMES[team][index],
          x,
          y,
          spawnX: x,
          spawnY: y,
          vx: 0,
          vy: 0,
          onGround: true,
          health: 100,
          maxHealth: 100,
          dead: false,
          facing,
          aimAngle: team === 0 ? -0.55 : Math.PI + 0.55,
          phase: this.rng() * Math.PI * 2,
          hurtTimer: 0,
          showPlate: 4,
          fallStart: y,
          weapon: 'bazooka',
          grave: null,
          recoil: 0,
        });
      });
    }

    this.currentWorm = this.worms[0];
    this.currentWorm.showPlate = 999;
    this.emit('refresh');
    this.emit('teams');
  }

  start() {
    if (this.phase === 'over') this.newMatch(Date.now() & 0x7fffffff, false);
    this.beginTurn(0, true);
  }

  emit(type, detail = {}) {
    this.onEvent({ type, ...detail });
  }

  toast(text, bad = false) {
    this.emit('toast', { text, bad });
  }

  playSound(name) {
    this.audio?.play?.(name);
  }

  // -------------------------------------------------------------------------
  // Turn flow
  // -------------------------------------------------------------------------

  beginTurn(team, first = false) {
    if (this.isOver) return;
    const alive = this.worms.filter((w) => w.team === team && !w.dead);
    if (!alive.length) {
      this.endMatch(1 - team);
      return;
    }
    this.currentTeam = team;
    let guard = 0;
    let worm = null;
    while (!worm && guard < 6) {
      const candidate = this.worms.find((w) => w.team === team && w.index === this.wormCursor[team]);
      if (candidate && !candidate.dead) worm = candidate;
      this.wormCursor[team] = (this.wormCursor[team] + 1) % 3;
      guard += 1;
    }
    if (!worm) worm = alive[0];

    for (const w of this.worms) {
      if (!w.dead) w.showPlate = w === worm ? 999 : 0;
    }
    this.currentWorm = worm;
    this.currentWorm.showPlate = 999;
    this.currentWorm.weapon = this.selectedWeapon[team];
    this.currentWeapon = this.currentWorm.weapon;
    this.phase = team === 0 ? 'player' : 'ai';
    this.timer = TURN_TIME;
    this.buildsLeft = 4;
    this.buildMode = false;
    this.chargePower = 0;
    this.charging = false;
    this.turnEnding = false;
    this.shotActive = false;
    this.endDelay = 0;
    this.harvestCooldown = 0;
    this.materials[team].wood = Math.min(999, this.materials[team].wood + 10);
    this.wind = Math.round(range(this.rng, -58, 58));
    if (first) this.wind = Math.round(range(this.rng, -24, 24));
    this.turn += first ? 0 : 1;
    this.stats.turns += 1;

    // Face the nearest enemy so the idle pose reads clearly.
    const enemies = this.worms.filter((w) => w.team !== team && !w.dead);
    const target = enemies.reduce((best, w) => {
      if (!best) return w;
      return Math.abs(w.x - worm.x) < Math.abs(best.x - worm.x) ? w : best;
    }, null);
    if (target) {
      worm.aimAngle = angleTo(worm.x, worm.y - 42, target.x, target.y - 20);
      worm.facing = target.x >= worm.x ? 1 : -1;
    }
    this.mouse.active = false;

    if (team === 0) {
      this.playSound('turn');
      this.toast(first ? 'YOUR TURN — BUILD, HARVEST, FIRE' : `YOUR TURN — ${worm.name} IS UP`);
      this.emit('turn');
    } else {
      this.aiState = 'think';
      this.aiTimer = 1.15;
      this.aiTarget = null;
      this.toast(pick(this.rng, AI_LINES), true);
      this.playSound('turn');
      this.emit('turn');
    }
    this.emit('refresh');
  }

  endTurn(manual = false) {
    if (this.phase !== 'player' && this.phase !== 'ai') return;
    if (this.shotActive) return;
    this.charging = false;
    this.chargePower = 0;
    if (manual && this.phase === 'player') this.toast('TURN PASSED');
    this.phase = 'switching';
    this.turnEnding = true;
    this.endDelay = 0.55;
    this.pendingTeam = 1 - this.currentTeam;
    this.emit('refresh');
  }

  updateTurnFlow(dt) {
    if (this.turnEnding) {
      this.endDelay -= dt;
      if (this.endDelay <= 0 && this.phase === 'switching') {
        this.turnEnding = false;
        this.beginTurn(this.pendingTeam ?? 1 - this.currentTeam);
      }
      return;
    }
    if (this.shotActive) {
      const hasLiveProjectiles = this.projectiles.length > 0;
      if (!hasLiveProjectiles) {
        this.shotActive = false;
        this.endDelay = 1.25;
        this.phase = 'resolving';
      }
      return;
    }
    if (this.phase === 'resolving') {
      this.endDelay -= dt;
      if (this.endDelay <= 0 && !this.isOver) this.endTurn(false);
      return;
    }
    if (this.phase === 'player') {
      this.timer -= dt;
      if (this.timer <= 0) {
        this.timer = 0;
        this.toast('OUT OF TIME', true);
        this.endTurn(false);
      }
    }
  }

  // -------------------------------------------------------------------------
  // Per-frame update
  // -------------------------------------------------------------------------

  update(dt) {
    dt = clamp(dt, 0, 1 / 24);
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 1.9);
    this.flash = Math.max(0, this.flash - dt * 2.6);
    this.hitVignette = Math.max(0, this.hitVignette - dt * 1.25);
    this.harvestCooldown = Math.max(0, this.harvestCooldown - dt);

    this.particles.update(dt, this.terrain);
    this.updateFloaters(dt);
    this.updateBuildings(dt);
    this.updateWorms(dt);
    this.updateProjectiles(dt);
    this.updateTurnFlow(dt);

    if (this.phase === 'ai' && !this.isOver) this.updateAI(dt);

    // Ambient island details
    if (this.phase === 'menu') {
      this.timer = TURN_TIME;
    }
  }

  updateFloaters(dt) {
    for (let i = this.floaters.length - 1; i >= 0; i -= 1) {
      const f = this.floaters[i];
      f.life -= dt;
      f.y += f.vy * dt;
      f.vy *= Math.pow(0.94, dt * 60);
      if (f.life <= 0) this.floaters.splice(i, 1);
    }
  }

  addFloater(x, y, text, color = '#ffe14a', size = 15) {
    this.floaters.push({ x, y, text, color, size, life: 1.25, maxLife: 1.25, vy: -52 });
  }

  updateBuildings(dt) {
    for (let i = this.buildings.length - 1; i >= 0; i -= 1) {
      const b = this.buildings[i];
      b.age = Math.min(1, b.age + dt * 7);
      if (b.fading) {
        b.life -= dt * 3;
        if (b.life <= 0) this.buildings.splice(i, 1);
      }
    }
  }

  // -------------------------------------------------------------------------
  // Worms
  // -------------------------------------------------------------------------

  updateWorms(dt) {
    for (const worm of this.worms) {
      if (worm.dead) continue;
      worm.hurtTimer = Math.max(0, worm.hurtTimer - dt);
      worm.recoil = Math.max(0, worm.recoil - dt * 5);
      if (worm.showPlate > 0 && worm.showPlate < 900) worm.showPlate -= dt;

      const controllable = this.phase === 'player' && worm === this.currentWorm;
      if (controllable) {
        let dir = 0;
        if (this.keys.left) dir -= 1;
        if (this.keys.right) dir += 1;
        if (dir !== 0 && !this.turnEnding) {
          worm.vx = approach(worm.vx, dir * WORM_SPEED, 980 * dt);
          worm.facing = dir;
        } else {
          worm.vx = approach(worm.vx, 0, 1250 * dt);
        }
        if (this.keys.jump && worm.onGround && !this.turnEnding) {
          worm.vy = -JUMP_SPEED;
          worm.onGround = false;
          worm.fallStart = worm.y;
          this.keys.jump = false;
          this.audio?.play('jump');
          this.particles.dust(worm.x, worm.y, 5);
        }
        if (this.mouse.active) {
          worm.aimAngle = angleTo(worm.x, worm.y - 42, this.mouse.x, this.mouse.y);
        }
      } else {
        worm.vx = approach(worm.vx, 0, 1320 * dt);
      }
      if (!worm.onGround) worm.vy = Math.min(1150, worm.vy + GRAVITY * dt);
      this.moveWorm(worm, dt);
    }
  }

  moveWorm(worm, dt) {
    const wasGround = worm.onGround;
    // Horizontal with small step-up support.
    if (Math.abs(worm.vx) > 0.5) {
      const nx = worm.x + worm.vx * dt;
      const probe = this.groundAt(nx, worm.y - 16, 30);
      let targetY = worm.y;
      if (probe !== null && probe >= worm.y - 15 && probe < worm.y - 0.5) targetY = probe;
      const tooHigh = probe !== null && probe < worm.y - 15;
      const blocked = this.blockedAt(nx, targetY, worm);
      if (!tooHigh && !blocked) {
        worm.x = nx;
        if (targetY < worm.y) worm.y = targetY;
      } else {
        worm.vx = 0;
      }
    }

    worm.x = clamp(worm.x, 12, WORLD.width - 12);

    // Vertical.
    const ny = worm.y + worm.vy * dt;
    if (worm.vy >= 0) {
      const drop = Math.max(4, ny - worm.y + 6);
      const support = this.groundAt(worm.x, worm.y - 3, drop);
      if (support !== null && ny >= support) {
        if (!wasGround) {
          const fall = support - worm.fallStart;
          if (fall > 175) {
            const dmg = Math.round((fall - 150) * 0.14);
            if (dmg > 0) this.damageWorm(worm, dmg, 'fall', true);
            this.shake = Math.max(this.shake, 0.15);
            this.particles.dust(worm.x, worm.y, 9);
            this.audio?.play('land');
          } else if (fall > 35) {
            this.particles.dust(worm.x, worm.y, 4);
          }
        }
        worm.y = support;
        worm.vy = 0;
        worm.onGround = true;
        worm.fallStart = support;
      } else {
        worm.y = ny;
        worm.onGround = false;
      }
    } else {
      worm.y = ny;
      worm.onGround = false;
      // stop upward motion if the head enters solid ground or a wall
      if (this.blockedAt(worm.x, worm.y, worm, true)) {
        worm.vy = 12;
      }
    }

    if (worm.y > WATER - 5) this.drownWorm(worm);
  }

  groundAt(x, fromY, maxDrop) {
    if (x < 0 || x > WORLD.width) return null;
    let best = null;
    const terrainY = this.terrain.groundBelow(x, Math.max(0, fromY), Math.min(WORLD.height, fromY + maxDrop));
    if (terrainY !== null) best = terrainY - 1;

    for (const b of this.buildings) {
      if (b.fading) continue;
      if (b.type === 'ramp') {
        if (x < b.x || x > b.x + b.w) continue;
        const t = (x - b.x) / b.w;
        const lineY = b.flip ? b.y + t * b.h : b.y + b.h - t * b.h;
        if (lineY >= fromY - 1 && lineY <= fromY + maxDrop) {
          const support = lineY - 1;
          if (best === null || support < best) best = support;
        }
      } else if (x >= b.x - 2 && x <= b.x + b.w + 2) {
        if (b.y >= fromY - 1 && b.y <= fromY + maxDrop) {
          const support = b.y - 1;
          if (best === null || support < best) best = support;
        }
      }
    }
    return best;
  }

  blockedAt(x, feetY, worm = null, ceiling = false) {
    if (x < 8 || x > WORLD.width - 8) return true;
    const points = ceiling
      ? [[x, feetY - 26], [x - 6, feetY - 20], [x + 6, feetY - 20]]
      : [[x - 6, feetY - 6], [x + 6, feetY - 6], [x - 6, feetY - 18], [x + 6, feetY - 18], [x, feetY - 30]];
    for (const [px, py] of points) {
      if (this.terrain.solidAt(px, py)) return true;
    }
    for (const b of this.buildings) {
      if (b.fading || b.type === 'floor' || b.type === 'ramp') continue;
      if (rectCircle(b.x, b.y, b.w, b.h, x, feetY - 18, 10)) return true;
    }
    return false;
  }

  drownWorm(worm) {
    if (worm.dead) return;
    worm.dead = true;
    worm.health = 0;
    worm.grave = null;
    this.particles.splash(worm.x, WATER + 2);
    this.particles.death(worm.x, WATER - 10, worm.team === 0 ? '#6ce9ac' : '#ff8790');
    this.playSound('splash');
    this.toast(`${worm.name} WENT SWIMMING`, true);
    this.emit('teams');
    this.checkTeamWipe();
  }

  // -------------------------------------------------------------------------
  // Projectiles and explosions
  // -------------------------------------------------------------------------

  muzzleFor(worm) {
    const angle = worm.aimAngle;
    return {
      x: worm.x + Math.cos(angle) * 30,
      y: worm.y - 42 + Math.sin(angle) * 26,
    };
  }

  fire() {
    if (this.phase !== 'player' && this.phase !== 'ai') return false;
    const worm = this.currentWorm;
    if (!worm || worm.dead) return false;
    const weaponName = worm.weapon || this.currentWeapon;
    if (weaponName === 'pickaxe') return false;
    const ammo = this.ammo[worm.team][weaponName];
    if (ammo <= 0) {
      this.toast('NO AMMO LEFT', true);
      this.playSound('deny');
      this.charging = false;
      return false;
    }
    const config = WEAPONS[weaponName];
    const power = clamp(this.chargePower, 0.16, 1);
    const muzzle = this.muzzleFor(worm);
    const speed = config.speed * power;
    const kind = weaponName === 'bazooka' ? 'rocket' : weaponName;
    this.projectiles.push({
      kind,
      x: muzzle.x,
      y: muzzle.y,
      vx: Math.cos(worm.aimAngle) * speed,
      vy: Math.sin(worm.aimAngle) * speed,
      gravity: config.gravity,
      blast: config.blast,
      damage: config.damage,
      radius: config.radius,
      ownerTeam: worm.team,
      owner: worm,
      life: 0,
      fuse: config.fuse ?? 0,
      spin: 0,
      trail: 0,
      ignore: 0.12,
      minis: kind === 'cluster' ? 4 : 0,
    });
    if (ammo !== Infinity) this.ammo[worm.team][weaponName] -= 1;
    this.stats.shots[worm.team] += 1;
    this.phase = 'firing';
    this.shotActive = true;
    this.charging = false;
    this.chargePower = 0;
    this.buildMode = false;
    this.shake = Math.max(this.shake, kind === 'rocket' ? 0.32 : 0.22);
    this.flash = Math.max(this.flash, 0.14);
    this.particles.muzzle(muzzle.x, muzzle.y, worm.aimAngle, kind === 'rocket' ? 1 : 0.7);
    this.particles.dust(worm.x, worm.y, 4);
    worm.recoil = 1;
    this.playSound('shoot');
    this.emit('refresh');
    return true;
  }

  updateProjectiles(dt) {
    if (!this.projectiles.length) return;
    const steps = Math.max(2, Math.ceil(dt / 0.006));
    const step = dt / steps;
    const windAccel = windToAccel(this.wind);

    outer: for (let i = this.projectiles.length - 1; i >= 0; i -= 1) {
      const p = this.projectiles[i];
      for (let s = 0; s < steps; s += 1) {
        p.vy += p.gravity * step;
        p.vx += windAccel * step;
        p.x += p.vx * step;
        p.y += p.vy * step;
        p.life += step;
        if (p.kind !== 'rocket') p.spin += step * (p.kind === 'cluster' ? 9 : 5);

        if (p.life < p.ignore) continue;
        if (p.x < -180 || p.x > WORLD.width + 180 || p.y < -500) {
          this.projectiles.splice(i, 1);
          continue outer;
        }
        if (p.y > WATER) {
          this.projectiles.splice(i, 1);
          this.particles.splash(p.x, WATER);
          this.playSound('splash');
          continue outer;
        }
        if (p.fuse > 0 && p.life >= p.fuse) {
          this.projectiles.splice(i, 1);
          this.explode(p.x, p.y, p.blast, p.damage, p.ownerTeam, p.kind);
          continue outer;
        }

        const hitPiece = this.pieceAtPoint(p.x, p.y);
        const hitTerrain = this.terrain.solidAt(p.x, p.y);
        if (hitPiece || hitTerrain) {
          if (p.kind === 'grenade') {
            this.bounceGrenade(p, hitPiece);
            break;
          }
          this.projectiles.splice(i, 1);
          this.explode(p.x, p.y, p.blast, p.damage, p.ownerTeam, p.kind);
          continue outer;
        }

        for (const worm of this.worms) {
          if (worm.dead) continue;
          if (p.life < 0.22 && worm === p.owner) continue;
          const dx = p.x - worm.x;
          const dy = p.y - (worm.y - 22);
          if (dx * dx + dy * dy < (12 + p.radius) ** 2) {
            this.projectiles.splice(i, 1);
            this.explode(p.x, p.y, p.blast, p.damage, p.ownerTeam, p.kind);
            continue outer;
          }
        }

        if (p.kind === 'rocket') {
          p.trail += step;
          if (p.trail > 0.016) {
            p.trail = 0;
            this.particles.rocketTrail(p.x, p.y, Math.atan2(p.vy, p.vx));
          }
        } else if (p.trail > 0.07) {
          p.trail = 0;
          this.particles.grenadeTrail(p.x, p.y);
        } else {
          p.trail += step;
        }
      }
    }
  }

  bounceGrenade(p, piece) {
    p.vy = -Math.abs(p.vy) * 0.46;
    p.vx *= 0.72;
    p.y -= 3;
    if (p.vy > -40) p.vy = -90;
    this.particles.dust(p.x, p.y, 4);
    this.playSound('bounce');
    if (p.fuse > 0 && p.life > p.fuse) return;
    if (piece) this.damageBuilding(piece, 8, p.ownerTeam, p.x, p.y);
  }

  explode(x, y, radius, damage, ownerTeam, kind = 'rocket') {
    this.particles.explosion(x, y, radius, {});
    this.shake = Math.max(this.shake, radius / 165);
    this.flash = Math.max(this.flash, 0.28);
    this.playSound('explode', radius / 90);
    this.terrain.destroyCircle(x, y, radius * 0.72);
    this.audio?.play('launch');

    // Buildings take a beating and often come down.
    for (let i = this.buildings.length - 1; i >= 0; i -= 1) {
      const b = this.buildings[i];
      if (b.fading) continue;
      const dist = rectDistance(b.x, b.y, b.w, b.h, x, y);
      if (dist < radius + 12) {
        const dmg = explosionDamage(dist, radius + 12, damage * 1.7);
        this.damageBuilding(b, dmg, ownerTeam, x, y, true);
      }
    }

    // Worms.
    for (const worm of this.worms) {
      if (worm.dead) continue;
      const bodyY = worm.y - 21;
      const dist = Math.hypot(worm.x - x, bodyY - y);
      if (dist < radius + 18) {
        const dealt = Math.round(explosionDamage(Math.max(0, dist - 8), radius + 18, damage));
        if (dealt > 0) {
          this.damageWorm(worm, dealt, 'blast', false);
          const force = clamp(1 - dist / (radius + 18), 0, 1);
          const a = Math.atan2(bodyY - y, worm.x - x);
          worm.vx += Math.cos(a) * force * 290;
          worm.vy = Math.min(worm.vy, -Math.abs(Math.sin(a)) * force * 320 - force * 120);
          worm.onGround = false;
          worm.fallStart = worm.y;
          this.addFloater(worm.x, worm.y - 56, `-${dealt}`, worm.team === 0 ? '#ff9b9b' : '#ffe14a');
          if (worm.team === 0) this.hitVignette = Math.max(this.hitVignette, 0.8);
        }
      }
    }

    if (kind === 'cluster') this.spawnBomblets(x, y, ownerTeam, radius);
    this.afterDamage();
  }

  spawnBomblets(x, y, ownerTeam, radius) {
    for (let i = 0; i < 4; i += 1) {
      const a = -Math.PI / 2 + (i - 1.5) * 0.55 + range(this.rng, -0.12, 0.12);
      const speed = range(this.rng, 160, 310);
      this.projectiles.push({
        kind: 'cluster',
        x,
        y: y - 6,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed - 40,
        gravity: 780,
        blast: radius * 0.62,
        damage: 28,
        radius: 5,
        ownerTeam,
        owner: null,
        life: 0,
        fuse: range(this.rng, 0.55, 0.95),
        spin: range(this.rng, 0, Math.PI),
        trail: 0,
        ignore: 0.1,
        minis: 0,
      });
    }
  }

  damageBuilding(piece, amount, ownerTeam, x, y, explosive = false) {
    if (piece.fading) return;
    piece.hp -= amount;
    piece.hp = Math.max(0, piece.hp);
    if (explosive) {
      this.particles.buildBurst(x, y, piece.material, false);
    }
    const idx = this.buildings.indexOf(piece);
    if (piece.hp <= 0 && idx >= 0) {
      this.buildings.splice(idx, 1);
      this.particles.buildBurst(piece.x + piece.w / 2, piece.y + piece.h / 2, piece.material, true);
      this.playSound(piece.material === 'metal' ? 'buildMetal' : 'build');
    }
  }

  afterDamage() {
    this.emit('teams');
    this.emit('refresh');
    this.checkTeamWipe();
  }

  damageWorm(worm, amount, source, quiet = false) {
    if (worm.dead) return;
    const dealt = Math.max(1, Math.round(amount));
    worm.health = Math.max(0, worm.health - dealt);
    worm.hurtTimer = 0.35;
    worm.showPlate = Math.max(worm.showPlate, 2.5);
    if (source === 'blast') {
      this.stats.damage[1 - worm.team] += dealt;
      this.particles.hurt(worm.x, worm.y - 24, worm.team === 0 ? '#ff6d72' : '#ffe14a');
      this.playSound('hurt');
    }
    if (worm.team === 0) {
      this.hitVignette = Math.max(this.hitVignette, 0.45);
    }
    if (worm.health <= 0) this.killWorm(worm);
    if (!quiet) this.emit('teams');
  }

  killWorm(worm) {
    if (worm.dead) return;
    worm.dead = true;
    worm.health = 0;
    worm.grave = { x: worm.x, y: this.groundAt(worm.x, worm.y - 40, 200) ?? worm.y };
    this.particles.death(worm.x, worm.y - 22, worm.team === 0 ? '#6ce9ac' : '#ff8790');
    this.shake = Math.max(this.shake, 0.3);
    this.flash = Math.max(this.flash, 0.2);
    this.addFloater(worm.x, worm.y - 66, 'WORM DOWN', worm.team === 0 ? '#ff9b9b' : '#ffe14a', 13);
    this.toast(`${worm.name} GOT STORMED`, worm.team === 0);
    this.playSound(worm.team === 0 ? 'hurt' : 'explode');
    this.emit('teams');
    this.checkTeamWipe();
  }

  checkTeamWipe() {
    if (this.isOver) return;
    for (const team of [0, 1]) {
      if (!this.worms.some((w) => w.team === team && !w.dead)) {
        this.endMatch(1 - team);
        return;
      }
    }
  }

  endMatch(winner) {
    if (this.isOver) return;
    this.isOver = true;
    this.phase = 'over';
    this.charging = false;
    this.chargePower = 0;
    this.turnEnding = false;
    this.isWinner = winner === 0;
    if (winner === 0) {
      this.particles.confetti(800, 260, 150);
      this.playSound('victory');
    } else {
      this.playSound('defeat');
    }
    this.emit('gameover', { winner, stats: this.stats });
    this.emit('refresh');
  }

  // -------------------------------------------------------------------------
  // Player actions
  // -------------------------------------------------------------------------

  setPointer(x, y, active = true) {
    this.mouse.x = x;
    this.mouse.y = y;
    if (active) this.mouse.active = true;
  }

  pointerDown() {
    if (this.phase !== 'player' || this.isOver) return;
    if (this.buildMode) {
      this.placeBuild();
      return;
    }
    if (this.currentWeapon === 'pickaxe') {
      this.harvest(this.mouse.x, this.mouse.y);
      return;
    }
    if (this.charging) return;
    this.charging = true;
    this.chargePower = 0;
    this.playSound('charge');
  }

  pointerUp() {
    if (this.charging && this.phase === 'player') {
      if (this.chargePower < 0.05) {
        this.charging = false;
        return;
      }
      this.fire();
    }
  }

  beginCharge() {
    if (this.phase !== 'player' || this.buildMode || this.currentWeapon === 'pickaxe') return;
    if (this.charging) return;
    this.charging = true;
    this.chargePower = 0;
    this.playSound('charge');
  }

  releaseCharge() {
    this.pointerUp();
  }

  toggleBuild(type) {
    if (this.phase !== 'player' || this.isOver) return;
    if (this.buildMode && (!type || this.selectedBuild === type)) {
      this.buildMode = false;
      this.toast('BUILD KIT STOWED');
      this.emit('refresh');
      return;
    }
    this.buildMode = true;
    this.selectedBuild = type || this.selectedBuild;
    this.charging = false;
    this.chargePower = 0;
    this.playSound('select');
    this.toast(`${this.selectedBuild.toUpperCase()} — CLICK TO PLACE`);
    this.emit('refresh');
  }

  setMaterial(material) {
    if (!['wood', 'brick', 'metal'].includes(material)) return;
    this.material = material;
    if (this.buildMode) this.toast(`${material.toUpperCase()} SELECTED`);
    this.playSound('ui');
    this.emit('refresh');
  }

  setBuildType(type) {
    if (!COST[type]) return;
    this.selectedBuild = type;
    this.buildMode = true;
    this.playSound('select');
    this.emit('refresh');
  }

  setWeapon(name) {
    if (this.phase !== 'player' || this.isOver) return;
    if (!WEAPONS[name]) return;
    if (name !== 'pickaxe') {
      const ammo = this.ammo[this.currentTeam][name];
      if (ammo !== undefined && ammo <= 0) {
        this.toast('NO AMMO LEFT', true);
        this.playSound('deny');
        return;
      }
    }
    this.buildMode = false;
    this.charging = false;
    this.chargePower = 0;
    this.currentWeapon = name;
    this.selectedWeapon[this.currentTeam] = name;
    if (this.currentWorm) this.currentWorm.weapon = name;
    this.playSound('select');
    this.emit('refresh');
  }

  buildCost() {
    return COST[this.selectedBuild] ?? 20;
  }

  ghostPiece() {
    const worm = this.currentWorm;
    if (!worm) return null;
    const gx = snap(this.mouse.x, BUILD_GRID);
    const gy = snap(this.mouse.y, BUILD_GRID);
    const type = this.selectedBuild;
    const size = SIZE[type];
    let x;
    let y;
    if (type === 'wall') {
      x = gx - size.w / 2;
      y = gy - size.h;
    } else if (type === 'floor') {
      x = gx - size.w / 2;
      y = gy - size.h / 2;
    } else {
      x = gx - size.w / 2;
      y = gy - size.h;
    }
    const flip = type === 'ramp' ? this.mouse.x < worm.x : false;
    return {
      type,
      x,
      y,
      w: size.w,
      h: size.h,
      flip,
      material: this.material,
      team: worm.team,
      hp: MATERIAL_HP[this.material],
      maxHp: MATERIAL_HP[this.material],
      age: 1,
      fading: false,
      life: 1,
      blueprint: true,
    };
  }

  getBuildGhost() {
    if (!this.buildMode || this.phase !== 'player') return null;
    const worm = this.currentWorm;
    const piece = this.ghostPiece();
    if (!worm || !piece) return null;
    const cost = this.buildCost();
    const mats = this.materials[worm.team][piece.material];
    let valid = true;
    let reason = '';
    const distance = rectDistance(piece.x, piece.y, piece.w, piece.h, worm.x, worm.y - 20);

    if (this.buildsLeft <= 0) {
      valid = false;
      reason = 'build limit';
    } else if (mats < cost) {
      valid = false;
      reason = 'no mats';
    } else if (distance > this.buildRange) {
      valid = false;
      reason = 'too far';
    } else if (piece.x < 10 || piece.x + piece.w > WORLD.width - 10 || piece.y < 18 || piece.y + piece.h > WATER - 18) {
      valid = false;
      reason = 'blocked';
    } else if (rectCircle(piece.x, piece.y, piece.w, piece.h, worm.x, worm.y - 18, 17)) {
      valid = false;
      reason = 'too close';
    } else if (!this.hasSupport(piece, worm)) {
      valid = false;
      reason = 'no support';
    }
    return { piece, valid, reason, distance, cost };
  }

  hasSupport(piece, worm) {
    // Touching terrain counts as anchored.
    const samples = piece.type === 'ramp' ? [
      [piece.x + 4, piece.y + piece.h - 4],
      [piece.x + piece.w / 2, piece.y + piece.h / 2],
      [piece.x + piece.w - 4, piece.flip ? piece.y + 4 : piece.y + piece.h - 4],
      [piece.x + 4, piece.y + piece.h / 2],
    ] : [
      [piece.x + piece.w / 2, piece.y + piece.h / 2],
      [piece.x + 3, piece.y + 3],
      [piece.x + piece.w - 3, piece.y + 3],
      [piece.x + 3, piece.y + piece.h - 3],
      [piece.x + piece.w - 3, piece.y + piece.h - 3],
    ];
    for (const [x, y] of samples) {
      if (this.terrain.solidAt(x, y)) return true;
    }
    for (const b of this.buildings) {
      if (b.fading) continue;
      const d = rectDistance(piece.x, piece.y, piece.w, piece.h, b.x + b.w / 2, b.y + b.h / 2);
      if (d < 52) return true;
    }
    const wormDistance = rectDistance(piece.x, piece.y, piece.w, piece.h, worm.x, worm.y - 20);
    return wormDistance < 110;
  }

  placeBuild() {
    const ghost = this.getBuildGhost();
    if (!ghost) return false;
    if (!ghost.valid) {
      this.toast(ghost.reason.toUpperCase(), true);
      this.playSound('deny');
      return false;
    }
    const piece = ghost.piece;
    piece.blueprint = false;
    piece.age = 0;
    piece.hp = MATERIAL_HP[piece.material];
    piece.maxHp = piece.hp;
    this.buildings.push(piece);
    this.materials[this.currentTeam][piece.material] -= ghost.cost;
    this.buildsLeft -= 1;
    this.stats.builds[this.currentTeam] += 1;
    this.particles.buildBurst(piece.x + piece.w / 2, piece.y + piece.h / 2, piece.material, true);
    this.playSound(piece.material === 'metal' ? 'buildMetal' : 'build');
    this.shake = Math.max(this.shake, 0.05);
    this.addFloater(piece.x + piece.w / 2, piece.y - 4, `-${ghost.cost} ${piece.material.toUpperCase()}`, '#d9c7ff', 10);
    if (this.buildsLeft <= 0) {
      this.buildMode = false;
      this.toast('BUILD LIMIT REACHED');
    }
    this.emit('refresh');
    return true;
  }

  harvest(x, y) {
    if (this.phase !== 'player' || this.isOver) return;
    if (this.harvestCooldown > 0) return;
    const worm = this.currentWorm;
    if (!worm) return;
    if (Math.hypot(x - worm.x, y - (worm.y - 20)) > 150) {
      this.toast('MOVE CLOSER TO HARVEST', true);
      this.playSound('deny');
      return;
    }
    this.harvestCooldown = 0.24;
    this.playSound('harvest');
    worm.recoil = 1;

    const piece = this.pieceAtPoint(x, y);
    if (piece) {
      const gain = piece.material === 'metal' ? 8 : piece.material === 'brick' ? 12 : 16;
      this.materials[worm.team][piece.material] = Math.min(999, this.materials[worm.team][piece.material] + gain);
      this.damageBuilding(piece, 60, worm.team, x, y, false);
      this.particles.harvest(x, y, piece.material === 'brick' ? ['#e28970', '#963c35'] : piece.material === 'metal' ? ['#d5eaff', '#6f88aa'] : ['#d8a267', '#8a572d']);
      this.addFloater(x, y - 10, `+${gain} ${piece.material.toUpperCase()}`, '#ffe14a', 12);
      this.emit('refresh');
      return;
    }

    if (this.terrain.solidAt(x, y)) {
      const surface = this.terrain.surfaceY(x);
      let mat = 'wood';
      let gain = 18;
      if (y > surface + 170) { mat = 'metal'; gain = 9; }
      else if (y > surface + 74) { mat = 'brick'; gain = 13; }
      this.terrain.carveMelee(x, y, 17);
      this.materials[worm.team][mat] = Math.min(999, this.materials[worm.team][mat] + gain);
      this.particles.harvest(x, y, mat === 'brick' ? ['#b9765f', '#e8a083'] : mat === 'metal' ? ['#a9c0dc', '#e6f3ff'] : ['#7edc64', '#9a6134']);
      this.addFloater(x, y - 8, `+${gain} ${mat.toUpperCase()}`, '#ffe14a', 12);
      this.emit('refresh');
      return;
    }

    this.toast('NOTHING TO HARVEST', true);
    this.playSound('deny');
  }

  // -------------------------------------------------------------------------
  // AI
  // -------------------------------------------------------------------------

  updateAI(dt) {
    if (!this.currentWorm || this.currentWorm.dead) {
      this.beginTurn(this.currentTeam);
      return;
    }
    if (this.aiState === 'think') {
      this.aiTimer -= dt;
      if (this.aiTimer <= 0) {
        const enemies = this.worms.filter((w) => w.team !== this.currentTeam && !w.dead);
        if (!enemies.length) return this.checkTeamWipe();
        this.aiTarget = enemies.reduce((best, w) => {
          if (!best) return w;
          const score = w.health + Math.abs(w.x - this.currentWorm.x) * 0.05;
          const bestScore = best.health + Math.abs(best.x - this.currentWorm.x) * 0.05;
          return score < bestScore ? w : best;
        }, null);

        if (this.buildsLeft > 0 && this.rng() > 0.55 && this.canAiBuild()) {
          this.aiBuild(this.aiTarget);
          this.aiState = 'settle';
          this.aiTimer = 0.6;
          return;
        }
        this.aiAim(this.aiTarget);
        this.aiState = 'charge';
        this.aiTimer = 0.95;
        this.chargePower = 0;
      }
    } else if (this.aiState === 'settle') {
      this.aiTimer -= dt;
      if (this.aiTimer <= 0) {
        this.aiAim(this.aiTarget);
        this.aiState = 'charge';
        this.aiTimer = 0.95;
        this.chargePower = 0;
      }
    } else if (this.aiState === 'charge') {
      this.aiTimer -= dt;
      this.chargePower = clamp(1 - this.aiTimer / 0.95, 0, 1);
      if (this.aiTimer <= 0) {
        this.aiState = 'fired';
        this.fire();
      }
    }
  }

  canAiBuild() {
    const worm = this.currentWorm;
    const cost = COST.wall;
    return this.materials[worm.team][this.material] >= cost && worm.y < WATER - 120;
  }

  aiBuild(target) {
    const worm = this.currentWorm;
    const dir = target.x >= worm.x ? 1 : -1;
    const material = this.materials[worm.team].metal > 60 ? 'metal' : this.materials[worm.team].brick > 40 ? 'brick' : 'wood';
    const cost = COST.wall;
    if (this.materials[worm.team][material] < cost) return;
    const x = worm.x + dir * 66 - 8;
    const y = worm.y - 84;
    const piece = {
      type: 'wall',
      x,
      y,
      w: SIZE.wall.w,
      h: SIZE.wall.h,
      flip: false,
      material,
      team: worm.team,
      hp: MATERIAL_HP[material],
      maxHp: MATERIAL_HP[material],
      age: 0,
      fading: false,
      life: 1,
      blueprint: false,
    };
    // don't bury the worm or float it in the sea
    if (y < 10 || rectCircle(piece.x, piece.y, piece.w, piece.h, worm.x, worm.y - 18, 22)) return;
    this.buildings.push(piece);
    this.materials[worm.team][material] -= cost;
    this.buildsLeft -= 1;
    this.stats.builds[worm.team] += 1;
    this.particles.buildBurst(piece.x + piece.w / 2, piece.y + piece.h / 2, material, true);
    this.playSound(material === 'metal' ? 'buildMetal' : 'build');
    this.addFloater(piece.x + piece.w / 2, piece.y - 4, 'COVER UP', '#ffb1b4', 10);
    this.emit('refresh');
  }

  aiAim(target) {
    const worm = this.currentWorm;
    const muzzle = this.muzzleFor(worm);
    const weapon = this.ammo[worm.team].cluster > 0 && this.rng() > 0.8 ? 'cluster' : 'bazooka';
    this.currentWeapon = weapon;
    worm.weapon = weapon;
    const config = WEAPONS[weapon];
    let best = { score: Infinity, angle: -Math.PI / 2, power: 0.8 };
    const windAccel = windToAccel(this.wind);
    const targetPoint = { x: target.x, y: target.y - 20 };
    const angles = 38;
    const powers = 8;
    for (let ai = 0; ai < angles; ai += 1) {
      const angle = -Math.PI + 0.2 + (Math.PI - 0.4) * (ai / (angles - 1));
      for (let pi = 0; pi < powers; pi += 1) {
        const power = 0.3 + 0.7 * (pi / (powers - 1));
        const result = this.simulateShot(muzzle, angle, power, config, targetPoint, windAccel);
        if (result < best.score) best = { score: result, angle, power };
      }
    }

    // A touch of error keeps the enemy dangerous but beatable.
    const err = range(this.rng, -0.032, 0.032);
    const powerErr = range(this.rng, -0.035, 0.035);
    const angle = best.angle + err;
    const power = clamp(best.power + powerErr, 0.25, 1);
    worm.aimAngle = angle;
    worm.facing = Math.cos(angle) >= 0 ? 1 : -1;
    this.aiPower = power;
    this.chargePower = 0;
    this.aiState = 'charge';
    this.aiTimer = 0.95;
    this.emit('refresh');
  }

  simulateShot(muzzle, angle, power, config, targetPoint, windAccel) {
    let x = muzzle.x;
    let y = muzzle.y;
    let vx = Math.cos(angle) * config.speed * power;
    let vy = Math.sin(angle) * config.speed * power;
    const dt = 1 / 60;
    let score = Infinity;
    for (let step = 0; step < 330; step += 1) {
      vy += config.gravity * dt;
      vx += windAccel * dt;
      x += vx * dt;
      y += vy * dt;
      if (x < -100 || x > WORLD.width + 100 || y > WATER) {
        score = Math.min(score, Math.hypot(x - targetPoint.x, y - targetPoint.y) + 120);
        break;
      }
      if (this.terrain.solidAt(x, y) || this.pieceAtPoint(x, y)) {
        const d = Math.hypot(x - targetPoint.x, y - targetPoint.y);
        score = step < 16 ? d + 240 : d;
        break;
      }
      const d = Math.hypot(x - targetPoint.x, y - targetPoint.y);
      if (d < 17) { score = 0; break; }
      score = Math.min(score, d);
    }
    return score;
  }

  // -------------------------------------------------------------------------
  // Queries
  // -------------------------------------------------------------------------

  pieceAtPoint(x, y) {
    for (let i = this.buildings.length - 1; i >= 0; i -= 1) {
      const b = this.buildings[i];
      if (b.fading) continue;
      if (b.type === 'ramp') {
        const { x: bx, y: by, w, h, flip } = b;
        const inside = flip
          ? pointInTriangle(x, y, bx, by, bx + w, by + h, bx, by + h)
          : pointInTriangle(x, y, bx, by + h, bx + w, by, bx + w, by + h);
        if (inside) return b;
      } else if (x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h) {
        return b;
      }
    }
    return null;
  }

  getAimPreview() {
    if (!this.currentWorm || this.currentWeapon === 'pickaxe') return null;
    const worm = this.currentWorm;
    const config = WEAPONS[this.currentWeapon] || WEAPONS.bazooka;
    const power = this.charging ? clamp(this.chargePower, 0.12, 1) : 0.62;
    const start = this.muzzleFor(worm);
    const points = makeTrajectoryPreview(start, worm.aimAngle, config.speed * power, config.gravity, this.wind, {
      maxPoints: 150,
      step: 1 / 55,
      maxTime: 5.5,
      solidAt: (x, y) => this.terrain.solidAt(x, y) || !!this.pieceAtPoint(x, y),
      bounds: { minX: 0, maxX: WORLD.width, waterY: WATER },
    });
    const impact = points.length ? points[points.length - 1] : null;
    return { points, impact, muzzle: start, power, angle: worm.aimAngle };
  }

  getCurrentHealth() {
    return this.currentWorm?.health ?? 0;
  }

  aliveCount(team) {
    return this.worms.filter((w) => w.team === team && !w.dead).length;
  }
}

