470:             this.shake = Math.max(this.shake, 0.15);
471:             this.particles.dust(worm.x, worm.y, 9);
472:             this.audio?.play('land');
473:           } else if (fall > 35) {
474:             this.particles.dust(worm.x, worm.y, 4);
475:           }
476:         }
477:         worm.y = support;
478:         worm.vy = 0;
479:         worm.onGround = true;
480:         worm.fallStart = support;
481:       } else {
482:         if (wasGround) worm.fallStart = worm.y;
483:         worm.y = ny;
484:         worm.onGround = false;
485:       }
486:     } else {
487:       worm.y = ny;
488:       worm.onGround = false;
489:       // stop upward motion if the head enters solid ground or a wall
490:       if (this.blockedAt(worm.x, worm.y, worm, true)) {
491:         worm.vy = 12;
492:       }
493:     }
494: 
495:     if (worm.y > WATER - 5) this.drownWorm(worm);
496:   }
497: 
498:   groundAt(x, fromY, maxDrop) {
499:     if (x < 0 || x > WORLD.width) return null;
500:     let best = null;
501:     const terrainY = this.terrain.groundBelow(x, Math.max(0, fromY), Math.min(WORLD.height, fromY + maxDrop));
502:     if (terrainY !== null) best = terrainY - 1;
503: 
504:     for (const b of this.buildings) {
505:       if (b.fading) continue;
506:       if (b.type === 'ramp') {
507:         if (x < b.x || x > b.x + b.w) continue;
508:         const t = (x - b.x) / b.w;
509:         const lineY = b.flip ? b.y + t * b.h : b.y + b.h - t * b.h;
510:         if (lineY >= fromY - 1 && lineY <= fromY + maxDrop) {
511:           const support = lineY - 1;
512:           if (best === null || support < best) best = support;
513:         }
514:       } else if (x >= b.x - 2 && x <= b.x + b.w + 2) {
515:         if (b.y >= fromY - 1 && b.y <= fromY + maxDrop) {
516:           const support = b.y - 1;
517:           if (best === null || support < best) best = support;
518:         }
519:       }
520:     }
521:     return best;
522:   }
523: 
524:   blockedAt(x, feetY, worm = null, ceiling = false) {
525:     if (x < 8 || x > WORLD.width - 8) return true;
526:     const points = ceiling
527:       ? [[x, feetY - 26], [x - 6, feetY - 20], [x + 6, feetY - 20]]
528:       : [[x - 6, feetY - 6], [x + 6, feetY - 6], [x - 6, feetY - 18], [x + 6, feetY - 18], [x, feetY - 30]];
529:     for (const [px, py] of points) {
530:       if (this.terrain.solidAt(px, py)) return true;
531:     }
532:     for (const b of this.buildings) {
533:       if (b.fading || b.type === 'floor' || b.type === 'ramp') continue;
534:       if (rectCircle(b.x, b.y, b.w, b.h, x, feetY - 18, 10)) return true;
535:     }
536:     return false;
537:   }
