539:   drownWorm(worm) {
540:     if (worm.dead) return;
541:     worm.dead = true;
542:     worm.health = 0;
543:     worm.grave = null;
544:     this.particles.splash(worm.x, WATER + 2);
545:     this.particles.death(worm.x, WATER - 10, worm.team === 0 ? '#6ce9ac' : '#ff8790');
546:     this.playSound('splash');
547:     this.toast(`${worm.name} WENT SWIMMING`, true);
548:     this.emit('teams');
549:     this.checkTeamWipe();
