564:   fire() {
565:     if (this.phase !== 'player' && this.phase !== 'ai') return false;
566:     const worm = this.currentWorm;
567:     if (!worm || worm.dead) return false;
568:     const weaponName = worm.weapon || this.currentWeapon;
569:     if (weaponName === 'pickaxe') return false;
570:     const ammo = this.ammo[worm.team][weaponName];
571:     if (ammo <= 0) {
572:       this.toast('NO AMMO LEFT', true);
573:       this.playSound('deny');
574:       this.charging = false;
575:       return false;
576:     }
577:     const config = WEAPONS[weaponName];
578:     const power = clamp(this.chargePower, 0.16, 1);
579:     const muzzle = this.muzzleFor(worm);
580:     const speed = config.speed * power;
581:     const kind = weaponName === 'bazooka' ? 'rocket' : weaponName;
582:     this.projectiles.push({
583:       kind,
584:       x: muzzle.x,
585:       y: muzzle.y,
586:       vx: Math.cos(worm.aimAngle) * speed,
587:       vy: Math.sin(worm.aimAngle) * speed,
588:       gravity: config.gravity,
589:       blast: config.blast,
590:       damage: config.damage,
591:       radius: config.radius,
592:       ownerTeam: worm.team,
593:       owner: worm,
594:       life: 0,
595:       fuse: config.fuse ?? 0,
596:       spin: 0,
597:       trail: 0,
598:       ignore: 0.12,
599:       minis: kind === 'cluster' ? 4 : 0,
600:     });
601:     if (ammo !== Infinity) this.ammo[worm.team][weaponName] -= 1;
602:     this.stats.shots[worm.team] += 1;
603:     this.phase = 'firing';
604:     this.shotActive = true;
605:     this.charging = false;
606:     this.chargePower = 0;
607:     this.buildMode = false;
608:     this.shake = Math.max(this.shake, kind === 'rocket' ? 0.32 : 0.22);
609:     this.flash = Math.max(this.flash, 0.14);
610:     this.particles.muzzle(muzzle.x, muzzle.y, worm.aimAngle, kind === 'rocket' ? 1 : 0.7);
611:     this.particles.dust(worm.x, worm.y, 4);
612:     worm.recoil = 1;
613:     this.playSound('shoot');
614:     this.emit('refresh');
615:     return true;
616:   }
