618:   updateProjectiles(dt) {
619:     if (!this.projectiles.length) return;
620:     const steps = Math.max(2, Math.ceil(dt / 0.006));
621:     const step = dt / steps;
622:     const windAccel = windToAccel(this.wind);
623: 
624:     outer: for (let i = this.projectiles.length - 1; i >= 0; i -= 1) {
625:       const p = this.projectiles[i];
626:       for (let s = 0; s < steps; s += 1) {
627:         p.vy += p.gravity * step;
628:         p.vx += windAccel * step;
629:         p.x += p.vx * step;
630:         p.y += p.vy * step;
631:         p.life += step;
632:         if (p.kind !== 'rocket') p.spin += step * (p.kind === 'cluster' ? 9 : 5);
633: 
634:         if (p.life < p.ignore) continue;
635:         if (p.x < -180 || p.x > WORLD.width + 180 || p.y < -500) {
636:           this.projectiles.splice(i, 1);
637:           continue outer;
638:         }
639:         if (p.y > WATER) {
640:           this.projectiles.splice(i, 1);
641:           this.particles.splash(p.x, WATER);
642:           this.playSound('splash');
643:           continue outer;
644:         }
645:         if (p.fuse > 0 && p.life >= p.fuse) {
646:           this.projectiles.splice(i, 1);
647:           this.explode(p.x, p.y, p.blast, p.damage, p.ownerTeam, p.kind);
648:           continue outer;
649:         }
650: 
651:         const hitPiece = this.pieceAtPoint(p.x, p.y);
652:         const hitTerrain = this.terrain.solidAt(p.x, p.y);
653:         if (hitPiece || hitTerrain) {
654:           if (p.kind === 'grenade') {
655:             this.bounceGrenade(p, hitPiece);
656:             break;
657:           }
658:           this.projectiles.splice(i, 1);
659:           this.explode(p.x, p.y, p.blast, p.damage, p.ownerTeam, p.kind);
660:           continue outer;
661:         }
662: 
663:         for (const worm of this.worms) {
664:           if (worm.dead) continue;
665:           if (p.life < 0.22 && worm === p.owner) continue;
666:           const dx = p.x - worm.x;
667:           const dy = p.y - (worm.y - 22);
668:           if (dx * dx + dy * dy < (12 + p.radius) ** 2) {
669:             this.projectiles.splice(i, 1);
670:             this.explode(p.x, p.y, p.blast, p.damage, p.ownerTeam, p.kind);
671:             continue outer;
672:           }
673:         }
674: 
675:         if (p.kind === 'rocket') {
676:           p.trail += step;
677:           if (p.trail > 0.016) {
678:             p.trail = 0;
679:             this.particles.rocketTrail(p.x, p.y, Math.atan2(p.vy, p.vx));
680:           }
681:         } else if (p.trail > 0.07) {
682:           p.trail = 0;
683:           this.particles.grenadeTrail(p.x, p.y);
684:         } else {
685:           p.trail += step;
686:         }
687:       }
688:     }
689:   }
690: 
691:   bounceGrenade(p, piece) {
692:     p.vy = -Math.abs(p.vy) * 0.46;
693:     p.vx *= 0.72;
694:     p.y -= 3;
695:     if (p.vy > -40) p.vy = -90;
696:     this.particles.dust(p.x, p.y, 4);
697:     this.playSound('bounce');
698:     if (p.fuse > 0 && p.life > p.fuse) return;
699:     if (piece) this.damageBuilding(piece, 8, p.ownerTeam, p.x, p.y);
700:   }
701: 
702:   explode(x, y, radius, damage, ownerTeam, kind = 'rocket') {
703:     this.particles.explosion(x, y, radius, {});
704:     this.shake = Math.max(this.shake, radius / 165);
705:     this.flash = Math.max(this.flash, 0.08);
706:     this.playSound('explode', radius / 90);
707:     this.terrain.destroyCircle(x, y, radius * 0.72);
708:     this.audio?.play('launch');
709: 
710:     // Buildings take a beating and often come down.
711:     for (let i = this.buildings.length - 1; i >= 0; i -= 1) {
712:       const b = this.buildings[i];
713:       if (b.fading) continue;
714:       const dist = rectDistance(b.x, b.y, b.w, b.h, x, y);
715:       if (dist < radius + 12) {
716:         const dmg = explosionDamage(dist, radius + 12, damage * 1.7);
717:         this.damageBuilding(b, dmg, ownerTeam, x, y, true);
718:       }
719:     }
720: 
721:     // Worms.
722:     for (const worm of this.worms) {
723:       if (worm.dead) continue;
724:       const bodyY = worm.y - 21;
725:       const dist = Math.hypot(worm.x - x, bodyY - y);
726:       if (dist < radius + 18) {
727:         const dealt = Math.round(explosionDamage(Math.max(0, dist - 8), radius + 18, damage));
728:         if (dealt > 0) {
729:           this.damageWorm(worm, dealt, 'blast', false);
730:           const force = clamp(1 - dist / (radius + 18), 0, 1);
731:           const a = Math.atan2(bodyY - y, worm.x - x);
732:           worm.vx += Math.cos(a) * force * 290;
733:           worm.vy = Math.min(worm.vy, -Math.abs(Math.sin(a)) * force * 320 - force * 120);
734:           worm.onGround = false;
735:           worm.fallStart = worm.y;
736:           this.addFloater(worm.x, worm.y - 56, `-${dealt}`, worm.team === 0 ? '#ff9b9b' : '#ffe14a');
737:           if (worm.team === 0) this.hitVignette = Math.max(this.hitVignette, 0.8);
738:         }
739:       }
740:     }
741: 
742:     if (kind === 'cluster') this.spawnBomblets(x, y, ownerTeam, radius);
743:     this.afterDamage();
744:   }
745: 
746:   spawnBomblets(x, y, ownerTeam, radius) {
747:     for (let i = 0; i < 4; i += 1) {
748:       const a = -Math.PI / 2 + (i - 1.5) * 0.55 + range(this.rng, -0.12, 0.12);
749:       const speed = range(this.rng, 160, 310);
750:       this.projectiles.push({
751:         kind: 'cluster',
752:         x,
753:         y: y - 6,
754:         vx: Math.cos(a) * speed,
755:         vy: Math.sin(a) * speed - 40,
756:         gravity: 780,
757:         blast: radius * 0.62,
758:         damage: 28,
759:         radius: 5,
760:         ownerTeam,
761:         owner: null,
762:         life: 0,
763:         fuse: range(this.rng, 0.55, 0.95),
764:         spin: range(this.rng, 0, Math.PI),
765:         trail: 0,
766:         ignore: 0.1,
767:         minis: 0,
768:       });
769:     }
770:   }
