772:   damageBuilding(piece, amount, ownerTeam, x, y, explosive = false) {
773:     if (piece.fading) return;
774:     piece.hp -= amount;
775:     piece.hp = Math.max(0, piece.hp);
776:     if (explosive) {
777:       this.particles.buildBurst(x, y, piece.material, false);
778:     }
779:     const idx = this.buildings.indexOf(piece);
780:     if (piece.hp <= 0 && idx >= 0) {
781:       this.buildings.splice(idx, 1);
782:       this.particles.buildBurst(piece.x + piece.w / 2, piece.y + piece.h / 2, piece.material, true);
783:       this.playSound(piece.material === 'metal' ? 'buildMetal' : 'build');
784:     }
785:   }
