960:   ghostPiece() {
961:     const worm = this.currentWorm;
962:     if (!worm) return null;
963:     const gx = snap(this.mouse.x, BUILD_GRID);
964:     const gy = snap(this.mouse.y, BUILD_GRID);
965:     const type = this.selectedBuild;
966:     const size = SIZE[type];
967:     let x;
968:     let y;
969:     if (type === 'wall') {
970:       x = gx - size.w / 2;
971:       y = gy - size.h;
972:     } else if (type === 'floor') {
973:       x = gx - size.w / 2;
974:       y = gy - size.h / 2;
975:     } else {
976:       x = gx - size.w / 2;
977:       y = gy - size.h;
978:     }
979:     const flip = type === 'ramp' ? this.mouse.x < worm.x : false;
980: 
981:     // Plant pieces that are dragged near the ground instead of leaving them
982:     // hovering a few pixels above it.
983:     const centerX = x + size.w / 2;
984:     const foot = y + size.h;
985:     const ground = this.terrain.groundBelow(centerX, foot - 34, foot + 30);
986:     if (ground !== null) {
987:       const top = ground - 1;
988:       if (type === 'floor') {
989:         if (Math.abs(top - y) <= 26) y = top;
990:       } else if (Math.abs(top - foot) <= 26) {
991:         y += top - foot;
992:       }
993:     }
994: 
995:     return {
996:       type,
997:       x,
998:       y,
999:       w: size.w,
1000:       h: size.h,
1001:       flip,
1002:       material: this.material,
1003:       team: worm.team,
1004:       hp: MATERIAL_HP[this.material],
1005:       maxHp: MATERIAL_HP[this.material],
1006:       age: 1,
1007:       fading: false,
1008:       life: 1,
1009:       blueprint: true,
1010:     };
1011:   }
