1013:   getBuildGhost() {
1014:     if (!this.buildMode || this.phase !== 'player') return null;
1015:     const worm = this.currentWorm;
1016:     const piece = this.ghostPiece();
1017:     if (!worm || !piece) return null;
1018:     const cost = this.buildCost();
1019:     const mats = this.materials[worm.team][piece.material];
1020:     let valid = true;
1021:     let reason = '';
1022:     const distance = rectDistance(piece.x, piece.y, piece.w, piece.h, worm.x, worm.y - 20);
1023: 
1024:     if (this.buildsLeft <= 0) {
1025:       valid = false;
1026:       reason = 'build limit';
1027:     } else if (mats < cost) {
1028:       valid = false;
1029:       reason = 'no mats';
1030:     } else if (distance > this.buildRange) {
